    EZTR_Basic_ReplaceText(0x0206, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05This looks pretty light.|11Well, don't just stand there--|11Press |B0 to grab it and use |BB|11to move it!|BF", NULL);
