    EZTR_Basic_ReplaceText(0x020A, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Hey, I'm trying to tell you|11something...|11This torch is still warm, too.|BF", NULL);
