    EZTR_Basic_ReplaceText(0x0212, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Wha...What are you, anyway? |11That song you played...|11That instrument...|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0213, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05...That instrument!!!|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0214, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Wait! That's it!|11Your instrument!!!|11|13|12The |01mask salesman|05 said that if|11you got back the |01precious thing|11|05that was stolen from you, he|11could return you to normal!|10Did you completely forget or|11what?|BF", NULL);
    EZTR_Basic_ReplaceText(0x0215, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05He gives me the creeps! That|11mask salesman was the...|11|1F|00|14Sorry...just thinking aloud.|11|12But |01three days|05? Even if we never|11sleep, that still leaves us with a|11measly |0172 hours|05!|11Talk about demanding!|10Well, don't just stand there!|11We're going to see the|11|01Great Fairy|05!|11|12Look, you wanna find the Skull|11Kid, don't you?|11|13|12The |01Great Fairy|05 will know what|11he's up to. She watches over|11everything.|11|12And just between you and me,|11the Skull Kid is no match for the|11|01Great Fairy|05.|11|12Go to the |01shrine|05 near the|11|01North Gate|05. You'll find the|11|01Great Fairy |05in there!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0216, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05That mask...|11|1F|00|28The Skull Kid uses the power of|11that mask to do those terrible|11things.|10Well...whatever it takes, we've|11gotta do something about it.|11|13|12...The |01swamp|05,|01 mountains|05, |01ocean |05and|11|01canyon|05 that Tael was trying to|11tell us about...|11|12I bet he was referring to the|11|01four areas|05 just outside town.|11There's one in each compass|11direction.|10But what do you suppose he|11meant by \"|01the four who are|11there|05?\"|11|12I have no idea. He always|11skips important stuff. I guess we|11should just go and find out...|11|12If we go through that gate|11straight ahead, we'll be heading in|11the direction of the |01swamp|05.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0217, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Oh! I remember this!|11|13|13|12|01Tael|05 and I drew this with the|11Skull Kid when we first met him...|BF", NULL);
    EZTR_Basic_ReplaceText(0x0218, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05He told us that he had been|11fighting with his friends and that|11they had left him all alone...|BF", NULL);
    EZTR_Basic_ReplaceText(0x0219, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05I'm sure it was because he was|11always playing tricks, so nobody|11wanted to play with him.|11|12But to do what he did just|11because of that...|BF", NULL);
    EZTR_Basic_ReplaceText(0x021A, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05And once he got his |01power|05...|BF", NULL);
    EZTR_Basic_ReplaceText(0x021B, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|25|05Oh no! The Great Fairy!|1C|00|14|BF", NULL);
    EZTR_Basic_ReplaceText(0x021D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Hey, aren't you going to the|11|01Great Fairy's shrine|05 near the|11|01North Gate|05?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x021E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05That Skull Kid has gone too far!|11We can't just let this happen!|11|13|12Quick! We have to find the|11|01Stray Fairy|05 in town and return|11the Great Fairy to normal!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x021F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05What are you doing?|11Aren't you gonna take this |01fairy|11|05to the |01shrine |05near the |01North|11Gate|05?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0220, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05The Great Fairy said the|11|01astronomer|05 knows the |01Skull Kid|05...|11|13|12Hurry! We need to find a way to|11get out of town and to the|11|01observatory|05!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0221, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05He said the |01secret route |05is in|11|01East Clock Town|05...|11So why aren't you going there?|11|12Don't tell me you forgot|11the |01code|05!!!|19|BF", NULL);
