    EZTR_Basic_ReplaceText(0x0223, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05What's the |01Skull Kid |05doing all the|11way up there?!|11|13|12Well, whatever...|11But aren't you at least interested|11in that thing that fell from the|11moon?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0224, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05The door to the clock tower opens|11only once a year--at |01midnight|05 on|11the eve of the |01carnival|05.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0225, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Did you hear those fireworks?|11I think the clock tower door has|11just |01opened|05!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0226, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Hey, you! C'mon! Press |B5 and|11talk to me!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0227, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05|17There you go! See? You can do it|11if you try!|18|11|13|12When I fly over to people or|11objects, use |B5 to look at them|11so you can talk to them.|11|12Use |01Z Targeting|05 to talk to people|11even if they're far away.|11 |11|12Or, if there's no one to target,|11you can use |B5 to look |01straight|11ahead|05. |11|12But enough about that for now...|11Come over to this |01tree |05and |01check|11|05it out!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0228, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05It's strange, but the way you look|11right now sort of looks like this|11tree...|11|12It looks all dark and gloomy...|11almost like it could start crying|11any second now...|11|1F|00|0AHow sad... |BF", NULL);
    EZTR_Basic_ReplaceText(0x0229, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05The |01four people|05 Tael talked|11about...|11|13|12Do you think he was talking about|11the spirit that was |01sealed inside|11|05that mask?|BF", NULL);
    EZTR_Basic_ReplaceText(0x022A, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05|17...Oh! Hey, you were pretty good|11out there!|18|11Have you done this before or|11what?|BF", NULL);
    EZTR_Basic_ReplaceText(0x022B, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Now, just keep up that pace and|11save the other |01three|05!|BF", NULL);
    EZTR_Basic_ReplaceText(0x022C, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Hey!|11|13|13|12Um...|BF", NULL);
    EZTR_Basic_ReplaceText(0x022D, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05All that stuff I did to you...|11...your horse...|11I...I apologize.|BF", NULL);
    EZTR_Basic_ReplaceText(0x022E, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05...Sorry.|BF", NULL);
    EZTR_Basic_ReplaceText(0x022F, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05There! I apologized!|11So don't hold it against me,|11got it?|BF", NULL);
    EZTR_Basic_ReplaceText(0x0230, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05Now then, we've helped the|11princess just like the monkey|11asked...|11|12So now our next stop is in the|11|01mountains|05! Let's hurry and do|11something about that Skull Kid!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0231, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05The quickest way to the |01mountains|11|05is through the |01North Gate|05!|BF", NULL);
