    EZTR_Basic_ReplaceText(0x05DC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|46Well, yours is a face I'm not used|11to seeing...|11|13|12Are you here to do something for|11me? I am Shikashi, professor of|11astronomy!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05DD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I have been enamored with the|11moon since I was a child.|11Now, I spend my days gazing at|11it from here.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05DE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The moon has long been|11considered a mystical body, which|11people have worshiped and feared.|11|12That alone shows how the moon|11has a cosmic influence that|11affects our daily lives.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05DF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But lately, there is something|11quite strange with the moon.|11Strange, indeed...|11|12It seems as though the moon is|11being pulled down by something|11and is slowly drawing closer.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E0, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "So, will you gaze into the|11telescope?|11|02|C2Yes|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...I see.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E2, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Why did you stop? |11Won't you look again?|11|02|C2Yes|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That is one of the lunar rocks|11that has been blazing from the|11surface of the moon lately.|11|12They fall from what looks to be|11the moon's eye, so I call them|11|01Moon's Tears|00.|11|12They are rare stones, valued by|11many in town.|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|46Did you have another question|11for me?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "To me, it seems as if the moon is|11being pulled in by something and|11is gradually drawing closer.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E6, 0x0B, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|BB:Move |B1:Quit |B0:Zoom|1A|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Don't you sense the change in the|11moon?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well...could you see it?|11It already may be impossible to|11stop its descent...|11|12All I can do is accept what the|11cosmos has designed to be the|11destiny for me and this planet.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x05E9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How was it?|11It's looking worse, isn't it?|11It would be nice if things just|11stayed as they are now.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x05EA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How was it?|11|13|13|12My calculations suggest the moon|11will fall in another |01|E7|00.|11I'm just hoping I was thinking too|11hard.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x05EB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, could you see it?|11This is no joke...the moon is|11actually falling!|11|12At this pace, it should hit the|11earth in just |01|E7|00...|11What can we possibly do?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x05EC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|46Well, well...A strange-looking child|11has joined me today...|11|13|12Are you a new friend of the|11Bombers gang?|11|13|12...Hmmm.|11Your manners seem much better|11than those of your mischievous|11friend from the other day.|10|1E|69|47Hrnf, hrnf, hrnf!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05ED, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That ill-mannered troublemaker|11from the other day said he'd|11break my instruments...|11|12He said he'd steal my |01Moon's Tear|00...|11There was no stopping him.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05EE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Even now! Just watch him! He's|11probably causing trouble around|11the |01clock tower|00.|19|BF", NULL);
