    EZTR_Basic_ReplaceText(0x05F0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, why not? You must take an|11interest in new things while you|11are still young!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05F1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, did you find that|11|01troublemaker|00?|11|13|12You can zoom in with |B0.|11Try looking near the |01clock tower|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x05F2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, did you find that|11|01troublemaker|00? And that loud|11noise...What was that?|11|12Perhaps another |01Moon's Tear|00 has|11fallen nearby...Go through that|11door and take a look outside.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05F3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But I wonder how that|11troublemaker got on top of the|11clock tower?|11|12The only way up there is through|11the clock door, and that opens|11only on the |01eve of the carnival|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x05F4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What could that |01troublemaker|00 be|11doing atop the |01clock tower|00?|11|13|12I just hope he's not plotting|11another one of his no-good|11tricks...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x05F5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, you're a child I've never seen|11in town before. Are you a new|11friend of the Bombers?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05F6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I always say that it is important|11to develop your interests while|11you are young!|11|12You can use this telescope to|11look around town. If you're|11interested, give it a try.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x05F7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, how was it? Did you|11discover anything interesting?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x05F8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, why not?|11You should develop your interests|11while you are still young!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x060E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|8BI've already sold out of my wares,|11and the carnival hasn't even|11begun.|11|12I'm thinking of closing up shop so|11I can buy a gift for my wife and|11return to her in my village!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x060F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|81I've heard that a stone called the|11|01Moon's Tear |00shines brighter than|11any other in the land!|11|12If you've got one, I'd really like|11to get it from you. My wife|11would love it!|11|12If you give it to me, I'll give you|11my spot here...|11|01Deku Flower|00 included!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0610, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|A7If you have a |01Moon's Tear|00, I must|11get it from you! My wife would|11love it!|11|12If you give it to me, I'll give you|11my spot here... |11|01Deku Flower|00 included!|11That's a good deal!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0611, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|D2Do you have one?|11|13|13|12You're a Deku Scrub, so you know|11just how convenient a |01Deku|11Flower|00 can be.|11|12If you don't hurry, I'll give it to|11another Deku Scrub. The early|11Scrub gets the nut!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0612, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|80Ah! That stone! You must hand it|11over to me!|11|13|12In exchange, I'll give you my spot|11here...|01Deku Flower |00included!|11Yes?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0613, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|81You really helped me out! Now I|11have the perfect souvenir for my|11wife!|11|12She hasn't set eyes on a jewel or|11strange, sparkling stone like this|11in a very long time.|11|12The |01Title Deed|00 for this spot|11should be in high demand among|11Deku Scrubs, but you already|11know that.|10|13If you don't need it anymore, you|11can always sell it!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0614, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|D1Sir! Sir!|11|13|13|12I keep hearing about a stone|11called a |01Moon's Tear|00, and it's|11supposed to be the shiniest stone|11in the world!|10Do you have one?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0615, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you have one, I'll trade you this|11spot and I'll throw in the Deku|11Flower, too!|11|12This is a very popular spot among|11Deku Scrubs. Haven't you heard|11about this spot? I'm telling you,|11it's a real bargain!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0616, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|D2Sir, if you have a |01Moon's Tear|00,|11I must get it from you...And I'm|11not asking to get it for free!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0617, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|80Ah!|11That stone! You must give it to|11me!|11|12In exchange, I'll give you my spot|11here, and I'll throw in this |01Deku|11Flower|00, too!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0618, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|8CIf you have a |01Moon's Tear|00, please|11tell me! I want one as a souvenir|11for my wife!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0619, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|81Sir, you've really helped me out!|11Now I have the perfect souvenir|11for my wife!|11|12She hasn't seen a jewel or|11strange, shining stone like this in|11quite a long time...Hee-hee!|11|12The |01Title Deed|00 for this spot will|11be in big demand by Deku Scrubs|11outside of town.|11|12You should be able to sell it to a|11Deku Scrub for a good price!|E0|BF", NULL);
