    EZTR_Basic_ReplaceText(0x0736, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|01Hey, |01|16|00.|11Are you writing in your notebook?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0737, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "1. Find troubled people and add|11    their names and pictures.|11    Only |0120 people|00 will fit in|11    your book.|102. Promise to help them.|11    Mark promises with |01Promise|11    Stickers|00. Don't be late|11    fulfilling your promises!|103. Whenever you solve someone's|11    problem, it makes you happy,|11    so a |01Happy Sticker |00will be|11    added to your book.|104. No removing stickers!|11    Use Promise Stickers to keep|11    track of people until everyone|11    is happy.|10Don't forget the rules!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0738, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|01The Bombers Secret Society of|11Justice forever!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x073A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You burst my balloon! |11Don't be messin' with other|11people's stuff! Ya won't be able|11to handle the consequences, pal!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x073B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You burst my balloon! |11Don't be messin' with other|11people's stuff! Ya won't be able|11to handle the consequences, pal!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x073C, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "There's a lot of |01cool stuff|00 at that|11telescope guy's place!|11|13|12Oh, yeah...and, um...|11|1F|00|04|17The Bombers Secret Society of|11Justice forever!|18|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x073D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How old are you? You're not from|11around here, are you? Why are|11you dressed like that?|11Why? Huh? Why?|10Do you have any problems? Any?|11If you do, tell it to us Bombers!|11Tell us!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x073E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh! A Goron! Do you live in the|11mountains? Why is Tatl with you?|11Why? Huh? Why?|11|12Do you have any problems? Any?|11If you do, you can tell us|11Bombers! Tell us!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x073F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh! A Zora! Do you live in the|11ocean? What's it like? Why is|11Tatl with you? Why? Huh? Why?|11|12Do you have any problems? Any?|11If you do, you can tell us|11Bombers! Tell us!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0740, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Psst...Wanna know about the|11Bombers?|11|02|C2Yes|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x0741, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Why don't you wanna know?|11Why? Why?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0742, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|01Heh, heh! You can't tell anyone!|11|13|13|12Every Bomber has a |01notebook|00!|11Here's how we use it:|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0743, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The Bombers gang is a Secret|11Society of Justice. You can't tell|11this to anybody...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0744, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|02What's with you? You're wearing a|11weird hat for a Deku! Did you|11come to town to play? I bet|11nobody will play with you, right?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0745, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The adults are all busy getting|11ready for the carnival!|11|13|12The |01old astronomer|00 at the|11|01observatory|00 outside town is the|11only one who'll spend any time|11playing with us kids.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0746, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The adults are busy trying to|11decide whether or not to hold the|11carnival!|11|12The |01old astronomer|00 at the|11|01observatory|00 outside town is the|11only one who'll spend any time|11playing with us kids!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0747, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We |01Bombers|00 have our |01hideout|00 at|11the |01observatory|00.|11|13|12You have to take a |01secret route|11|00to get to it.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0748, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh! Don't be telling |01Jim |00in |01North|11Clock Town |00that I told you that!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0749, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The |01secret route|00 to the|11|01Observatory|00? How do you know|11about that?|11|12Only |01Jim|00 and us are supposed to|11know about that |01secret route|00...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x074A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Don't tell anyone that you heard|11about the secret route from me,|11got it?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x074B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|01Hey, buddy! Have you found any|11troubled people? If you do, add|11'em to your |01notebook|00!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x074C, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Do you remember how to use your|11|01notebook|00?|11|02|C2Yes|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x074D, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "All right! The Bombers Secret|11Society of Justice forever!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x074E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Did you memorize the |01code|00?|11If only you were human...then I|11could make you a |01Bombers|11|00member...Too bad!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x074F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|03You're pretty good for|11a Deku Scrub!|11|13|12If only you were human...|11|13|13|12Then I could give you an original|11|01Bombers' Notebook|00 and make you a|11member...|11|12What do you guys think?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0750, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "No way! No Scrubs!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0751, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I guess not...Once, we let some|11kid who wasn't human join our|11gang, and, boy, did we ever regret|11it! Sorry!|10But I'll teach you the |01code|00, just|11like I promised. I can tell you only|11|01once|00, though, so pay close|11attention!|10Are you ready?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0752, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The code is |01|DF|00!|11The entrance to our |01hideout |00is in|11|01East Clock Town|00!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0753, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|03Are you the guy who just popped|11that up there?|11Whoa!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0754, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey, just for you, guy, I can make|11you a member of our gang, the|11|01Bombers|00!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0755, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But there is a test for becoming|11a |01Bombers |00member. C'mon!|11Give it a try!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0756, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Are you ready?|11|02 |11|C2Yes|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x0757, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you can find all|01 five |00of us by|11|01tomorrow morning|00, I'll teach you|11our secret code. Ready?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0758, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|00What's the deal, guy?|11You dress like you think you're all|11cool, but you're nothing special!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0759, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What? Whaddya mean?!|11Don't you want to join the|11|01Bombers|00?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x075A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Do you remember the code?|11It's |01|DF|00!|11|13|12Go to the |01secret hideout|00 before|11you forget it! It's in |01East Clock|11Town|00!|E0|BF", NULL);
