    EZTR_Basic_ReplaceText(0x080B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|8F...Your Highness!|11I am begging you! Please calm|11down!|E0|BF", NULL);
