    EZTR_Basic_ReplaceText(0x08DB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "By the way...|1F|00|14|17|01who|00 are you?|18|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x08DC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...Whoa!|11That's not important now...|11Just listen to me!|BF", NULL);
    EZTR_Basic_ReplaceText(0x08DD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I was trying to find out about the|11poison in the swamp, so I went to|11|01Woodfall Temple|00 above the|11waterfall.|10But the temple had become a|11|01monster's lair|00, and the princess|11was captured by the monster...|11|12Since the Deku king thinks I|11kidnapped the princess, he won't|11listen to a word I say.|11|12Now the princess is in trouble, so|11I must somehow hurry to the|11|01temple|00 and save her!|BF", NULL);
