    EZTR_Basic_ReplaceText(0x0BEC, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "So, will you proceed?|11 |11|02|C2Yes|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BED, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hoo-Hoot!|11You are a child of many|11strengths!|11|12Well, perhaps you do have enough|11strength to change the fate of|11this mountain after all.|11|12I shall take to the air now, flying|11toward that shrine across the|11way, so follow behind me.|11|12|01Do not be daunted by|11appearances|00. Instead, let your|11feelings guide you, and the true|11path shall open before you.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BEE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Are you ready?|11Follow behind me!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BEF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I shall pass no judgment.|11If that is your decision, then|11return to town.|11|12After retreat, courage returns.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BF0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What is it that you are doing?|11Beyond here you will fall into |11oblivion unless you have great|11courage and determination.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BF1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It seems things are not going well|11for you...Hoo-Hoot! Fear not, it|11never goes well at first for|11anyone.|10But by no means should you|11grow impatient. Impatience brings|11uneasiness and distracts the|11heart.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BF2, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, will you try again?|11 |11|02|C2Yes|11No|BF", NULL);
