    EZTR_Basic_ReplaceText(0x0BF4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Very good. I shall fly toward that|11shrine. Follow behind me.|11|13|12|01Do not be daunted by|11appearances|00. Instead, let your|11feelings guide you, and the true|11path shall open before you.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BF5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hoo-Hoot!|11I have certainly been assured of|11your courage and determination.|11|12From here on, you must not be|11fooled by appearances. You must|11rely on your feelings...|11|12Now, enter the |01shrine|00. Something|11that will aid you in your quest|11lies within. Use that|01 item|00 when|11returning from here.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BF6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ho-ho-ho-ho-hoot!|11This is a rare sight. You are a|11fairy child, correct?|11|12What business might you have in|11this poisoned swamp?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BF7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you dare not venture further,|11I shall pass no judgment.|11It is better that you hurry back|11to town.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BF8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This swamp you are in has lost|11its guardian deity. But it was|11destined to fade anyway.|11|12Hoo-hoot...And that destiny is not|11solely limited to this swamp...|19|BF", NULL);
