    EZTR_Basic_ReplaceText(0x0BFD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Remember it well and play it|11wherever the need arises.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BFE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "From the first time you play this|11song, we shall become eternal|11friends, transcending time and|11place!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0BFF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Notes are carved in the stone...|BF", NULL);
