    EZTR_Basic_ReplaceText(0x0DC4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|1CIt's not that I forgot it. It's just|11so cold that I can't play very|11well...|11|12...At any rate, I am counting on|11you.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DC5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|FCHuh?|11|13|13|12...Let me play it once more.|15|BF", NULL);
