    EZTR_Basic_ReplaceText(0x0DC7, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How does this song go?|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DC8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Umm...|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DC9, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBAh, yes, yes! Like this!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DCA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04|17It's no good!|18|11I can remember only the|11beginning!|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DCB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|FCOh! Welcome to spring in Goron|11Village!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DCC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBYou're just in time...|11We're holding the Goron Races in|11celebration of spring, so go see|11them!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DCD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04Oh! Darmani!|11I've been waiting impatiently for|11you.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DCE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBI have been waiting for your|11arrival ever since I heard the|11news...|11|12I had heard that you, the one|11whom I once thought to be dead,|11had sealed off the blizzard that|11was blowing in from Snowhead.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DCF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBThanks to you, spring has come|11to Goron Village. Everyone is|11pleased!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD0, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BDThe greatest Goron hero of all?|11That's...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD1, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BC|17Darmani!|18|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BDThe immortal Goron who|11is not dead, even if he has died?|11That's...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BDThe star whom we wish upon?|11That's...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BDDarmani, greatest of Gorons!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD5, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BCGreatest of Gorons!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BDDarmani is the greatest in the|11world!!!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD7, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BCGreatest in the world!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|1CMy son got better immediately.|11He went to see the Goron Races|11that celebrate spring.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DD9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This time, I, the protector of this|11tribe for so many years, choose|11to yield the seat of tribal|11patriarch to a younger one.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DDA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The Goron who makes calm|11decisions, yet boasts courageous|11determination and can take care|11of all shall be the patriarch!|19|BF", NULL);
