    EZTR_Basic_ReplaceText(0x0DDC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...What do you think? If it's you,|11everyone would happily accept you|11as the patriarch.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DDD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What? You need not answer so|11quickly. Go, enter the Goron Race.|11Think it over slowly. I am awaiting|11a thoughtful response.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DDE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBCome back to me with your|11decision after you have entered|11the Goron Race and thought about|11it carefully.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DDF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "My son should be anxiously|11awaiting your arrival.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DE0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBNow, quickly go beyond the|01 Twin|11Islands Cave |00after leaving Goron|11Village.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DE1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Spring has finally come to Goron|11Village. Please go see the Goron|11Races held in honor of spring. |E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DE2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Darmani!|11The Goron Elder has been waiting|11impatiently for you!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DE3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Darmani!|11Are you going to enter the Goron|11Races, too?|19|BF", NULL);
