    EZTR_Basic_ReplaceText(0x0DE5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBSpring has finally come to Goron|11Village. It's just starting to get|11comfortably warm. It feels nice.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DE6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BB|17Darmani!|18|11The Goron Elder has been waiting|11impatiently for you!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DE7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04|17Darmani!|18|11You really are alive!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DE8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm feeling like a complete fool. |E0|BF", NULL);
