    EZTR_Basic_ReplaceText(0x0DEA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BB|17Darmani!|18|11The Goron Elder has been waiting|11for you!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DEB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04|17Darmani!|18|11You did it!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DEC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That's just like you to pretend to|11be dead just so your enemies will|11let their guard down.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DED, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|FCDo you already have bombs,|11the special product of the|11Gorons?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DEE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "There's a Goron in this village who|11sells |01Powder Kegs|00, which are much|11more powerful explosives.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DEF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBIf you're interested, you should|11drop by Goron Village Cave.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BB|17Darmani!|18|11The Goron Elder is waiting|11impatiently for you!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04|17Darmani!|18|11So you're alive after all!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I was so completely fooled that|11I even made a grave for you.|11I'm so dumb.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBSpring has finally come to Goron|11Village. Now we can dig up the|11rock sirloin that had been beneath|11the ice.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But that has nothing to do with|11you. Sorry.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BB|17Darmani!|18|11The Goron Elder is waiting|11impatiently for you!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04|17Darmani!|18|11You...You are alive.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You always did say, \"I cannot die|11until I've eaten 1000 tons of rock|11sirloin!\"|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|FCYou...Do you know much|11about the moon?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DF9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It's just that, lately, I think the|11moon has been getting bigger.|11I couldn't help but notice it. What|11do you think?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DFA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BB|17Darmani!|18|11The Goron Elder is waiting|11impatiently for you!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DFB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|1C|17Darmani|18, you sure are amazing,|11but...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DFC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But somehow...I still have a bad|11feeling about things...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DFD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|FDYou...You feel it too, don't you?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DFE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It's spring! It's spring!|11I can't sit still any longer!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0DFF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Darmani! Are you ready? I'm rarin'|11to go!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E02, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Spring has finally come!|11I have been waiting for this|11moment.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E03, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This year is my debut at the|11races...Please go easy on|11me!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E04, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Since it has warmed up...|11my spirits have lifted!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E05, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This year, I'm feeling a little|11different...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E06, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Watch my race!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E07, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Darmani!|11Are you entering after all?|11...I guess I'll be last again.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E10, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4This is the grave where a Goron|11hero rests.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E11, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I came here to put up the great|11hero's memorial...|11|13|12But the return route has been|11blocked by snow, and I can't get|11back to Goron Village.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E12, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And even worse, my brother has|11been frozen solid from the cold.|11|13|12The way things are looking, I'll be|11frozen, too.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E13, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|1COhhhh...It's times like this that|11make me wish I had taken some of|11the |01hot spring water|00 I found when|11I was digging the hero's grave.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E14, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But the hot spring is now covered|11by the gravestone. I can't move a|11gravestone that big by myself.|11|12|1E|38|FDBut I guess this is what's meant|11by the Goron saying, \"There's no|11use in crying over split rocks.\"|11...Brrrrrr.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E15, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|FDH-h-hooo. If only I had water from|11the |01hot spring |00beneath the great|11hero's |01grave|00...then I could melt the|11ice off of my brother.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E16, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Y-you're...No! No, you're not|11|1E|3A|04the great Darmani, are you?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E17, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|FCThen...just whose grave was I|11making?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E18, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Did you come back to life|11because it was so warm beneath|11your grave?|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E19, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4There used to be a hot spring|11bubbling beneath the great|11Darmani's grave.|11 |10If I had some of that |01hot spring|11water|00, I might be able to thaw out|11my frozen brother.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E1A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4Hunh?|11What have I been doing?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E1B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04Oh!!! Are you all right, brother?|11You were frozen, but the great|11Darmani saved you!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E1C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The great Darmani?!|11What's with you? Are you half|11asleep?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E1D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Did you hear this guy?|11The great Darmani died long ago|11and is lying in his gr...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E1E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04Heeee!!! Darmani!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E1F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I was shocked, too.|11But somehow, it seems the great|11Darmani isn't dead.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E20, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "R-Really?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E21, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "With this, a star of hope appears|11in Goron Village.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E22, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Great Darmani! Please do|11something about the blizzard|11blowing in from |01Snowhead|00!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E23, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04Oh! Are you all right, brother?|11You were frozen and this person|11saved you!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E24, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Frozen?!|11...I was?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E25, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...Really? I don't know who you|11are, |1E|39|1Cbut thank you!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E26, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But besides that, it turns out the|11great Darmani is alive!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E27, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What's this?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E28, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I was shocked, too, but somehow|11it seems the great Darmani is not|11dead.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E29, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Really?|11If that's true, then a glimmer of|11hope has appeared in Goron|11Village.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E2A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It's true! Surely the great|11Darmani can do something about|11the blizzard that blows in from|11|01Snowhead|00.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E2B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4Great Darmani!|11Hurry! Please do something about|11the blizzard blowing in from|11|01Snowhead|00.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E2C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4Great Darmani!|11Have you seen the Goron Elder|11yet?|11|12If you haven't, you should go see|11him soon. I'm sure he'll be very|11happy.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E2D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4Do you know the great|11Darmani? He is the greatest hero|11of the Goron tribe. He is our|11last hope.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E2E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4Have you seen the great|11Darmani? No one can withstand|11his punching and pounding.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E2F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4H-h-hoooo...It's cold.|11This cold has me hallucinating|11about Darmani. I can't take it.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E30, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4H-h-hoooo...It's cold.|11This cold has me seeing Darmani's|11ghost...Y-Yikes...|11I th-think I'll go freeze again...|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E31, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Thank you for saving my brother.|11|13|13|12But something has to be done|11about this cold. Otherwise, |1E|38|B4we'll|11be Goronsicles.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E32, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|B4H-h-hoooo...It's cold.|11I wonder if we'll ever be able to|11return to Goron Village.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E42, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBThis is great.|11The Elder's son has finally quit|11crying. Now we can sleep, too.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E43, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|1CWe're at our wits' end...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E44, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The Elder went to Snowhead and|11doesn't seem to be coming back.|11Now his son is so lonely that he|11won't stop crying.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E45, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It keeps getting colder outside,|11and inside we're so cold we could|11freeze.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E46, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04Those sideburns...Aren't you|11Darmani? You're supposed to be|11dead...but you're alive?|11|12The Elder was troubled because he|11thought you were dead.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E47, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|1CI'm troubled, too...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E48, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The Elder went to Snowhead and|11hasn't come back, so now his son|11is so lonely he won't stop crying.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E49, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you don't find the Goron Elder|11and ask him to come back...I'll|11never be able to sleep.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E4A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And it just keeps getting colder|11outside...Even in here it is so cold|11that we could freeze.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E4B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBAt his age, the Elder couldn't|11have gotten very far.|11|13|12I fear that he may be frozen out|11there...|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E4C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04This is nice.|11The Elder's son has finally stopped|11crying. Now we can sleep, too.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E4D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBThis is the room of the Goron|11Tribe's Elder.|11|13|12Do you have some kind of|11business with the Elder?|11Unfortunately, he's out.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E4E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|39|1CSince the Elder is gone, his son|11won't stop crying. I wish someone|11would do something...|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E4F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|04Those sideburns...Aren't |11you Darmani? You're supposed to|11be dead...but you're alive?|11What have you been doing?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E50, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Thinking you were dead, |1E|39|1Cthe Elder|11went to |01Snowhead|00 on his own...|11|13|12But for now, please go see the|11Elder's son. Hurry!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E51, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The Elder's son is in there.|11|1E|39|1C...This crying is heartbreaking.|11Will it ever stop?|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E52, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|BBThis store is having trouble|11getting product because of the|11cold. Things are kind of expensive|11now, so you shouldn't shop here.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E74, 0x00, 0x00, 0xFE, 0x0E75, 0xFFFF, 0xFFFF, true, "|1E|38|E9Waaa...Hunh, ugh...u-waahhh!|11Da-daaaddy, daaaddy! Hunh...|11I'm cooooold...Daaaddy!|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E75, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|E9...Hyunh, hunh...|11Ahh, Darmi, where's my daddy?|11Where's my daddy?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E76, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|38|E9Waaah...Henh, uwaaaaah...|11Daaaaaddy, daaaddy...H-hunh...|11I'm cooold, Daaaddy!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E77, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That song...That's the song daddy|11always plays for me before I|11go to sleep...|11I'll sing the next part.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E78, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|18Mmmmm...|11It's just like...|1F|00|0Adaddy's...|11|1F|00|0Aright...|1F|00|0Abeside me...|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E79, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Zzzzz...|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E7A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|C9Ah, Darmi!|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E7B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Now that it's nice and warm out,|11I'm much, much better.|11|13|12Even if my daddy isn't right beside|11me, I won't be selfish and cry.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E7C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "So...now that spring has come, the|11Goron Races should be starting|11soon.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E7D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But...|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E7E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But this rock is in the way, so I|11can't get in to see the race...|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E7F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|18And spring's just started, too...|11I was so excited...but there's|11nothing I can do...|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E80, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17I hate it!|18 |17I hate it!|18|11|17I wanna see it!|18|11|17I wanna see it!|18|11I wanna see the race!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E81, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17Break it!|18 |17Break it!|18|11|17I wanna go to the race!|18|11I wanna go to the race!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E82, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|C9Did you come to play?|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E83, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you can, you should go see the|11Goron races that are gonna be|11held on the other side of this|11mountain.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E84, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|C8Way to go, Darmi!|11That was cooool!|11|13|12C'mon! If we don't hurry, the race|11will start. C'mon! Hurry!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E85, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|C8The Goron Races that honor the|11coming of spring are about to|11begin.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E86, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It's a really, really cool race, so|11you should watch it.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E87, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Once you see these Goron races,|11you'll wish you were born a Goron.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E88, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|C9Ah! Darmi!|11I've been waiting for you.|11|13|12See, everyone's restless 'cause|11they can't wait to enter. You're|11gonna enter, aren't you?|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E89, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You're gonna enter aren't you?|11 |11|02|C2Yep|11Nope|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E8A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...You used to like racing more|11than you liked gobbling up a third|11helping of rock sirloin...|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E8B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|18The Darmi I know would never|11back out of a race...|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E8C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I hate it!|11I wanna watch you race!|11|17I wanna!|18 |17I wanna!|18 |17I wanna!|18|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E8D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...|1E|3A|C8You really do want to race.|11I know you do.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E8E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|C8You have to! I want to show|11everyone how Darmi races!|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E8F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If your |02magic power |00runs low,|11charge it up with the |02green jars|11|00on the course.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E90, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|C8That was great!|11I knew you were the fastest|11Goron, Darmi!|11|12I was sure you'd get first place!|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E91, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This is from daddy...|11It's the prize.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E92, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I wanna be just like you--quick!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E93, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...You're just a little stiff because|11winter was so long.|11|13|12You're not really like this.|11|13|13|12Remember how good you really|11are, then enter the races again.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E94, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, but if you don't have an|11empty bottle to keep the prize in,|11you can't enter...|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E95, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|48|4EEveryone, one entrant made a|11false start, so we must restart|11the race.|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E97, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Can you hear me, Darmi? Umm...|11I'm sorry, but there's no way you|11can win now...|11|12Do you want to keep racing|11anyway?|11|02|C2Of course!|11No...|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E98, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|3A|C8C'mon...Enter the race.|11I want to show everybody how|11fast you are.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x0E99, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You did it!|11Thanks a lot!|11|13|12I'm going right in. I'll be waiting|11for you, so you have to come|11see it!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|48They're late!|11What are those Zoras doing?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|49Hmm? What is it, boy?|11Did you also come to watch the|11Zora eggs hatch?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm excited about it, too, but|11those important eggs haven't|11arrived yet...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It takes about one to three days|11from the time Zora eggs are laid|11for them to hatch.|11|12But if they aren't kept in this|11|01aquarium|00 until then...they may die.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The reason for this is that the|11recent abnormal weather has|11caused the ocean temperature to|11rise in this region.|10|01Zora eggs |00are very sensitive to|11changes in the temperature.|11|13The only way the eggs can hatch|10is if they're placed in this|11|01aquarium water|00, which I set aside|11for them long ago.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|48The Zoras are well aware of|11this, but they're still late.|11I wonder if something has|11happened at |01Zora Hall|00?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|48They're late!|11What are those Zoras doing?|11If they don't hurry, the eggs will|11die.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This is a problem. Zora eggs won't|11hatch unless |01all eggs|00 that were|11laid at the same time are brought|11|01together|00.|10What are those Zoras doing?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|49What are you doing here? You|11look a little out of place at the|11ocean, don't you think?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FA9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The seas around here are too|11warm and aren't suitable for you|11to splash around in.|11|12If you don't have any business|11here, then be on your way.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FAA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "These seas are too warm for you|11to splash around in. If you haven't|11any business here, then be on|11your way.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FAB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And besides, the more I think|11about it, the funnier it looks|11seeing a fellow like you at the|11ocean.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FAC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|49What are you doing? Don't you at|11least shut your mouth when you're|11listening to people?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FAD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The seas around here are too|11warm and aren't suitable for you|11to splash around in.|11|12If you don't have any business|11here, then be on your way.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FAE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "These seas are too warm to|11splash around in. If you haven't|11any business here, then be on|11your way.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FAF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Are you really getting what I'm|11saying to you when you just stand|11there with your mouth wide open?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What happened to the rest of the|11eggs? The eggs can't hatch if|11they aren't all together.|11|12Hurry! Find the rest of the eggs|11and put them in the aquarium.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, you finally came? I've been|11waiting for you. What about the|11eggs?|11|12I heard there is a total of |01seven|00...|11Hurry! Put them in that |01aquarium|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you don't hurry, the eggs will|11die. Quickly! Put them in that|11aquarium!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Good. All of the eggs have been|11brought together.|11...It's going to start. Quick! Come|11to the front of the aquarium!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4AL-look at this! What does this|11mean...What in the world could|11this mean?|11|12...I've got it!|11|13|13|12Don't you understand? The way|11these Zora children have lined|11up...It means...|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You...Don't you have some kind of|11|01instrument|00?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "......|1F|00|14|11Nothing. Not a thing. Could it be|11you're using the wrong|11instrument?|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4AThat! Yes, it's that instrument!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hmm...|11If these Zoras were born to teach|11this song, then hurry!|11|12You must play this|01 song |00for the|11Zora who laid these eggs!|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FB9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I will take good care of the Zora|11children. You go find the |01Zora|11who laid these eggs|00! Quickly!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FBA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...This is a very strange thing.|11|13|13|12If Zora children can teach music,|11then the Zora still hold many|11mysteries.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FBB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What happened?|11Just what kind of song was that?|11|13|12You must know something, don't|11you?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FBC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I don't understand what happened,|11but it seems the ocean has|11reclaimed its serenity.|11|12Could this somehow be related to|11that song? You know something,|11don't you?|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FBD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The ocean's temperature has|11returned to normal. Did you come|11here to splash around in the sea?|11|12If you drown trying to swim with|11a big ol' body like that, don't|11blame me!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FBE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The ocean's temperature has|11returned to normal. Did you come|11here to splash around in the sea?|11|12If you try swimming with that|11puny body, you'll be sorry!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x0FBF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If they don't hurry, the eggs will|11soon die. What could the Zoras be|11doing?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1004, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|73Unghhh...|11|1F|00|0ASomebody...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1005, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|72Unghh...|11|1F|00|0APlease...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1006, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|73G-gu-hu...|11|1F|00|0AGet me...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1007, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1F|00|0A|1E|69|72...to shore...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1008, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|73Uuungh...I am |01Mikau|00 of the Zora|11people...|1F|00|0A...guitarist in the |01Zora|11band|00...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1009, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|72I think this is it for me...|11My final |1F|00|0Amessage...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x100A, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|73...Will you listen to it?|11 |11|02|C2I'll listen|11I won't listen|BF", NULL);
    EZTR_Basic_ReplaceText(0x100B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1F|00|0A|17One!|18 |1F|00|0A|17Two!|18 |1F|00|0A|17Three!!!|18|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x100C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|74Oh, baby, baby, listen to me!|11The carnival's beginning soon.|11We're the ones they're waiting to|11see.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x100D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|75But |01that girl|00, our vocalist...|11She laid some strange |01eggs|00.|11And she's lost her voice,|11You can't hear what she says.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x100E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|74Whoa-oh! In |01Great Bay|00 now|11somethin' is a-happenin'.|11|1F|00|0A|17Is it now?|18|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x100F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh! |1E|69|75Baby, listen to me.|11I don't wanna beg.|11|01Gerudo Pirates|00!|11They stole that girl's eggs.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x1010, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|74I went to stop the Gerudo Pirates,|11then pow and bam!|11I got knocked down,|11and here I am!|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x1011, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|75Baby! If I die like this...|11Even if I die...|11It won't be in peace...|11|1F|00|0A|17That's for suuure!|18|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x1012, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|74Somebody, please rescue her eggs|11before the pirates take their toll.|11Oh, somebody, somebody,|11please |01heal my soul|00.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x1013, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That's all...|11|1F|00|0A|1E|69|76|17Thank you!|18|BF", NULL);
    EZTR_Basic_ReplaceText(0x1014, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|72Gugh-hunh...|11M-my eyes...Everything's all hazy...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1015, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|73Soon, I'll be just another wave in|11the ocean...destined to disappear.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1016, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|74Oh, yeah! That hot sound shoots|11right to my heart.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1017, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Carve my farewell song on my|11grave...|11|1F|00|0AI'm depending on you to help that|11singer girl...|BF", NULL);
    EZTR_Basic_ReplaceText(0x1018, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Herein lies Mikau, the legendary|11guitarist of the Zora tribe. He is|11to be remembered in song, and his|11lyrics are written here.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1019, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Will you try to sing Mikau's|11lyrics?|11|13|12 |11|02|C31. We the Zora|112. Zora Fight Song|11I won't sing|BF", NULL);
    EZTR_Basic_ReplaceText(0x101A, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|76Sharp fins are the mark of the|11Zora. We |01swim|00, speeding through|11the seas with |B0 and |BB.|11|12If |B4 is pressed when swimming,|11a shield is produced to deflect|11enemies.|11(Spoken) If you have magic.|10We can even dive by pressing |B1!|11Oh-oh...We the Zora.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x101B, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|76For my punch of anger, hit|11|B1. Press |B1 repeatedly for a|11flurry of attacks! Yeah, yeah.|11|12For my deadly move, press and|11hold |B1. Now release! It's the|11final blow. My double cutters!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x101C, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Lulu's Diary|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x101D, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It has been two days since I have|11lost my voice.|11|13|12I don't want Mikau to know, so I|11talked to Evan about it.|11|13|12He recommended that I take the|11eggs to the Marine Research Lab|11to have them checked.|11|12I think I will take them right|11away.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x101E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Such a terrible thing has happened|11today that I don't even know|11where to begin writing.|11|12I heard a sound late at night, and|11when I opened my eyes, I saw|11strangers in my room.|11|12I tried to fight, but they were|11able to steal my precious eggs.|11|13|12It seems I lost consciousness|11after that.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x101F, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Today, I told everything to Mikau,|11the one person whom I didn't|11want to know about it.|11|12At first, I was too embarrassed|11and too sad to do anything.|11|13|12And with the words that Mikau|11said at that moment, I felt that|11all hope had been lost.|11|12But please, Mikau, I'm begging you,|11don't do anything rash.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1020, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, ".........|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1021, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05That sad face is trying to tell you|11something.|11...You can see it in her|11expression!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1022, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau, what's going on?|11|13|13|12And my voice...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1023, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What happened to me?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1024, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Who are you?|11Mikau...Where's Mikau?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1025, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mm...Mm...Yeeeaaawn!|11I slept quite well!|BF", NULL);
    EZTR_Basic_ReplaceText(0x1026, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I just realized this when I opened|11my eyes. The passing of days is|11quite quick. Isn't it, Lulu?|BF", NULL);
    EZTR_Basic_ReplaceText(0x1027, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Yes, Lulu. It's nothing to be|11surprised at.|11|13|12Although my eyes were closed in|11sleep, I still see everything that|11occurs in this ocean...|BF", NULL);
    EZTR_Basic_ReplaceText(0x1028, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...Hmm.|11It seems Lulu is confused.|11Regrettably, there is no time for|11idle conversation.|10Now then, proud Zora warrior...|BF", NULL);
    EZTR_Basic_ReplaceText(0x1029, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The open seas of Great Bay have|11need of your might.|11|13|12Quickly. Climb onto my back.|BF", NULL);
    EZTR_Basic_ReplaceText(0x102A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Why so slow?|11Hurry up and fire your |01hookshot|11|00into the palm |01tree|00 on my back,|11|16.|BF", NULL);
    EZTR_Basic_ReplaceText(0x102B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Heh, heh, heh.|11Of course I know your name.|11Didn't I say that all is seen by|11me?|BF", NULL);
    EZTR_Basic_ReplaceText(0x102C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You seem to be having a bit of|11trouble...|11|13|12Are you still not used to your|11Zora body?|11|13|12Perhaps it would be quicker to|11give up.|BF", NULL);
    EZTR_Basic_ReplaceText(0x102D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you are once again ready to|11depart, then climb onto my back.|11|13|12Ready, |16?|BF", NULL);
    EZTR_Basic_ReplaceText(0x102E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What's wrong?|11Returning to shore?|11|13|12Hyeh, hyeh.|BF", NULL);
    EZTR_Basic_ReplaceText(0x102F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It is not shameful to retreat. That|11in and of itself is a strategy.|11|13|12All right. Climb onto my back.|BF", NULL);
    EZTR_Basic_ReplaceText(0x1030, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Now I can continue resting in|11peace. I too must abide the laws|11of ancient times and again merely|11watch from my deep slumber.|10But the evil that haunts this land|11has not completely vanished,|11|16. I shall depart after|11enjoying Lulu's voice a bit longer.|10I think the gods can permit that.|11Hyeh, hyeh, hyeh.|BF", NULL);
    EZTR_Basic_ReplaceText(0x1031, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Pleased to meet you. I'm Lulu.|11|13|13|12Please come to our concert in|11town.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1032, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I guess being able to sing is a|11wonderful thing, after all...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1033, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17Mikau!|11You came back safely!|18|11|13|12That's good...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1034, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I was surprised when my voice|11turned that lonely island into a |11turtle... |19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1035, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But that song you played for|11me...My mother used to sing it|11often...long ago...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1036, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Those eggs were laid to remind me|11of that.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1037, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That song was from when I was a|11very young child, so I had|11forgotten it...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1038, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I've put you through some horrible|11experiences, Mikau.|11|13|12But I'm all better now!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1039, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, the town's concert is very|11soon.|11|13|12Let's start our rehearsal!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x103A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1F|00|14|17One...|18 |1F|00|14|17two...|18 |1F|00|14|17three...|18|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x103B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...Are you going to the temple|11again?|11|13|12If there is something left to do,|11then quickly climb onto my back.|BF", NULL);
    EZTR_Basic_ReplaceText(0x103C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "P--p-please...|11My soul...|11|01Heal |00it...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1068, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You have strange powers,|11|16. I have a request for|11you. Please follow me.|BF", NULL);
    EZTR_Basic_ReplaceText(0x1069, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Here in the depths of Pinnacle|11Rock live many dangerous sea|11snakes...|11|12My friend is trapped here.|11|13|13|12|16, can you please find a|11way to rid the area of all the|01 sea|11snakes|00 and help my friend?|BF", NULL);
    EZTR_Basic_ReplaceText(0x106A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Please do this for me. Please|11defeat all the vicious sea snakes|11and save my friend.|BF", NULL);
    EZTR_Basic_ReplaceText(0x106B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Please follow me closely without|11making any missteps.|BF", NULL);
    EZTR_Basic_ReplaceText(0x106C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you try to go beyond Pinnacle|11Rock, you'll get lost in the murky|11water.|11|12Before you know it, you'll find|11yourself back where you started,|11so be careful.|BF", NULL);
    EZTR_Basic_ReplaceText(0x106D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Thank you, |16.|11This is a symbol of my deepest|11gratitude.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x106E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Help me...|11Please, take me back to the|11waters near Pinnacle Rock...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x106F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4CAre you interested in that fish?|11|13|13|12It's a rare fish, isn't it?|11It's called a sea horse.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1070, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I caught it swimming around here.|11Just off of Pinnacle Rock.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1071, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Since it's rare, I was thinking of|11selling it at the town carnival,|11which should be starting soon.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1072, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you want, I'll give it to you.|11|13|13|12On one condition...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1073, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Do you have a |01pictograph|00 of the|11|01female pirates|00?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1074, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you want that sea horse, bring|11me a |01pictograph|00 of a |01female|11pirate|00.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1075, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4DOh! That's my |01hookshot |00that the|11pirates stole!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1076, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...If you have it, then that means|11you've been to the |01Pirates'|11Fortress|00.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1077, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "In that case, you've got one, don't|11you? Don't hide it!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1078, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|60What's this? I guess you don't|11have one after all.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1079, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Technically, I do have a |01pictograph|11|00of a |01female pirate|00, but it's all|11blurry and it's not that great...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x107A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The all-important face...I can't see|11it very well!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x107B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4DOh! That's it! That's it!|11I had a picture like that.|11|13|12Well, aren't you a crafty one?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x107C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You'll give that to me, won't you?|11|13|13|12In exchange, I'll give you this!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x107D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Thank you.|11Hurry! Take me back to the|11waters near Pinnacle Rock...|1C|00|28|BF", NULL);
    EZTR_Basic_ReplaceText(0x107E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "With pictographs, the sepia tone|11conveys a lot more emotion than|11color. Isn't it great?|11|12This picture you gave me is gonna|11be one of my treasures.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x107F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4BWell, if it isn't a Zora?|11How have things been going|11lately?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1080, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Har-harrr!|11...Could you be coming to see me|11'cause you can't catch any fish?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1081, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4EIt's not good out there...|11Lately, I've been coming back|11empty-handed myself.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1082, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Why, I was almost hoping you|11were coming to share with me!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1083, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Sorry, but I don't have any fish to|11share with you.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1084, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I've been catching fish in these|11seas for 30 years.|11|13|12When it comes to catching fish,|11I'm even better than the Zoras.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1085, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4E...That's what I'd like to be saying,|11anyway.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1086, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Lately, the seawater has gotten|11really warm.|11|13|12It hasn't helped my fishing at all...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1087, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And what's worse, this water has|11gotten murky, so when I ship out,|11I always lose my way and|11somehow end up back at shore.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1088, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We fishermen--and even the|11fish--are in a real predicament!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1089, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If the seas don't return to normal|11soon...|11|13|12The Zoras...and even I...will be|11all dried up!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x108A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4BHeh-heh! Isn't she pretty?|11|13|13|12But, you know...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x108B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Those female pirates are so|11frightening, they could scare a|11crying baby into silence...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x108C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "See, it was long ago when I used|11to use this thing called a|11hookshot to catch fish off the|11coast...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x108D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But I was attacked by these|11pirates, and they took it away|11with them.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x108E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "They say...|11it's a legendary treasure..|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x108F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And I just happened to swipe it|11from the bottom of the sea, so I|11hold no grudge against 'em.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1090, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It may be a treasure resting|11somewhere in the Pirates' Fortress|11at the edge of this coast.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1091, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The security at the Pirates'|11Fortress is tight. Sneaking in is|11no easy task.|11|12If you're set on meeting those|11beautiful pirates, try going to the|11|01valley |00on the other side of town!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1092, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I've heard there's a |01mask|00 there|11that lets the wearer escape|11|01detection|00.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1093, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Come to think of it, there was a|11|01Zora |00floating lifelessly out in the|11|01bay|00...|11|12But there's probably no helping him|11now...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1094, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, sorry! |01Evenings|00 and the first|11thing in the |01morning|00 are my |01break|11times|00. Come back later.|BF", NULL);
    EZTR_Basic_ReplaceText(0x1095, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4CNow that the seas are back to|11normal, I've started a little|11business aimed at tourists.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1096, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you pay |0620 Rupees|00, I'll invite|11you to a |01jumping game|00 that has a|11really |01big prize|00!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1097, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you're up for it, go to that|11island in the |01center|00.|BF", NULL);
    EZTR_Basic_ReplaceText(0x1098, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4B|17Oh, you're up for it!|18|11|13|13|12Now then, I'll explain the rules, so|11listen carefully.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1099, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm going to light the |01torches|00 on|11each of the surrounding |01four|11islands |00in a particular order.|11|12|01Jump|00 to the island that has the|11|01lit torch|00. If you can jump to it|11before the torch goes out, you'll|11get |01one point|00!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x109A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you get |0120 or more points|11|00within the time limit, you'll get a|11big prize! But it'll cost you|11|0620 Rupees|00 for one try.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x109B, 0x00, 0x00, 0xFE, 0xFFFF, 0x0014, 0xFFFF, true, "|1E|69|4BHow about it? Will you give it a|11try?|11|02|C2Sure|11No thanks|BF", NULL);
    EZTR_Basic_ReplaceText(0x109C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4BAw, that's too bad!|11And it's so fun, too.|11You're missing out...|BF", NULL);
    EZTR_Basic_ReplaceText(0x109D, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4EHmmm...|11You don't have enough |06Rupees|00.|11Maybe next time.|BF", NULL);
    EZTR_Basic_ReplaceText(0x109E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4BGreat!|11In that case, I'll start.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x109F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17Oh, that's out of bounds. That's|11against the rules!|18|11|13|12Huh? Didn't I tell you?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4EOh, yeah...|11If you fall, then that's that.|11You'll have to try again.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A1, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "All right...That's it!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4BWhat do you think?|11It's harder than it seems, isn't it?|11|13|12Some things in this world just|11look easy until you try them. But I|11know you'll try again!|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4EUh-oh!|11That was a little too easy...|11Oh well, here's your |01prize|00!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And I was thinking of saving up|11to buy a big ship...|11|13|12Now it looks like I may go|11bankrupt!|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Thank you for saving me.|11|13|13|12I know it may be asking too much,|11but I have a request for you,|11brave one.|11|12Please bring back my |01friend|00 who|11was caught by the |01fisherman|00.|11|13|12I beg you. You're the only one I|11can rely on.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Any good picture of a pirate will|11do--even a snapshot of a guard.|11Can't you help me out?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, and if you're going to the|11Pirates' Fortress, don't forget to|11take your pictograph box.|11|12...Ah, well, it's not that you have|11to take it...|11Heh, heh, heh...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, too bad.|11You don't have an |01empty bottle|00 to|11keep the sea horse in!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x10A9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Umm...|11Well, this certainly is a pirate...|11|13|12But I can't be pleased with a shot|11that looks like this.|11|13|12Bring me one that's a better shot|11of a pirate.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x10CE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|1AYou again?|11You can't fool me with your|11|02green clothes|00!|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x10CF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|1AYou want an |01empty bottle|00, don't|11you? You never learn your lesson!|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x10D0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|1AKoo, koo, koo.|11OK, I'll give you one. |11|13|12But...|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x10D1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|1AOnly if you can swim through all|11the |01rings|00 in the river in under|11|01two minutes|00.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x10D2, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "So, do you wanna try?|11 |11|02|C2Sure|11No thanks|BF", NULL);
    EZTR_Basic_ReplaceText(0x10D3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|1AThe way out is over there!|BF", NULL);
    EZTR_Basic_ReplaceText(0x10D4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|1AKoo, koo, koo.|11If you want an |01empty bottle|00, I can|11give you one...|11|12But only if you can swim through|11all the|01 rings|00 in the river in under|11|01two minutes|00.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x10D6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|1AThere's a total of |0120 rings|00. You|11must swim through them in the|11right order for it to count. Swim|11through the ring that's|01 flashing|00.|10I'll show you the way, so follow|11me and don't get separated!|BF", NULL);
    EZTR_Basic_ReplaceText(0x10D7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "OK...Time's up!|BF", NULL);
    EZTR_Basic_ReplaceText(0x10D8, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Want to try again?|11 |11|02|C2Sure|11No thanks|BF", NULL);
    EZTR_Basic_ReplaceText(0x10D9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The way out is over there!|BF", NULL);
    EZTR_Basic_ReplaceText(0x10DA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|1AYou cheated, didn't you?|11You didn't get all the rings!|BF", NULL);
    EZTR_Basic_ReplaceText(0x10DB, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Wanna try again?|11 |11|02|C2Sure|11No thanks|BF", NULL);
    EZTR_Basic_ReplaceText(0x10DC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|29|1AThe way out is over there!|BF", NULL);
