    EZTR_Basic_ReplaceText(0x11F8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6BWhat's with you?|11|13|13|12This room belongs to |01Japas|00, the|11genius bassist of the Zora Band.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x11F9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Go through my manager if you|11want my autograph.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x11FA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The concert's coming soon. Let's|11forget about our bandmates and|11their messed-up problems and|11have a jam session of our own.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x11FB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6B|17Mikau!!!|18|11|13|13|12Where've ya been?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x11FC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm all, like, \"Hey, where's Mikau?|11The concert's comin' up soon!\"|11|13|12And now our band leader has|11pulled a vanishing act--Evan's all|11holed up in his room just writin'|11songs...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x11FD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And to top it off, |01Lulu|00 just|11stands out back starin' at the|11sea. She doesn't even respond|11when ya talk to her.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x11FE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you guys think it's just 'cause|11Lulu's not interested in me, I'd|11understand, but I'm tellin' ya, it|11looks like somethin's really wrong.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x11FF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Is there somethin' you're trying to|11hide from me?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1200, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm not runnin' an inquiry or|11anything...|11|13|12But, look...If we don't start|11rehearsin' real soon, we're not|11gonna be ready for the concert.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1201, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What were the other band|11members doing?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1202, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You do know that if we don't|11start rehearsing, we're not gonna|11be ready for the concert, right?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1203, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey...Why don't we forget about|11waiting for Evan to write a song|11and just write one ourselves?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1204, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you feel up to it, let's have a|11little jam session.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1205, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Did you play our song for Evan?|11|1F|00|08What did he say?|11|13|12Don't tell me...|11|13|13|12You didn't forget the song, did|11you?|11|02|C2Yeah, I did|11No, I didn't|BF", NULL);
    EZTR_Basic_ReplaceText(0x1206, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, in that case, hurry up and|11play Evan our song.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1207, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, man. In that case, I guess we|11have to have another jam session.|11Are ya ready?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1208, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6BHuh?|11You wanna have a jam session?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1209, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Try following this phrase I wrote|11on your guitar.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x120A, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Here we go...|BF", NULL);
    EZTR_Basic_ReplaceText(0x120B, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6BWhoooa...|11That's niiiice.|BF", NULL);
    EZTR_Basic_ReplaceText(0x120C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1F|00|04|17I got it!|18 |1F|00|04|17I got it!|18 |1F|00|04|17I got it!|18|11|1F|00|04Here I go!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x120D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6BThat's got a good feel to it! Even|11Evan should like this.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x120E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But...|11|13|13|12He's so proud...He'd resent the|11fact that we wrote somethin' on|11our own. I don't think he'd even|11let the others try it out.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x120F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Whaddya think we should do?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1210, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How can we, like, make sure that|11Evan doesn't find out that it was|11us who wrote this song?|11|12Can't you think of anything?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1211, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That melody's bogus, man!|11|13|13|12What's wrong? You're not jammin'|11like you usually do!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1212, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You wanna stop?|11 |11|02|C2Yeah|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x1213, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You in a slump?|11Don't worry about it...|11|13|12Those were the kind of notes an|11amateur would play while tryin' to|11figure out the notes as he goes...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1214, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6BOnce you're back in the groove,|11we'll write a song that'll knock|11Evan off his flippers!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1215, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "When you're in a slump, all ya|11can do is go back to your room|11and sleep on it.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1216, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That's uncool, man...|11What are you tryin' to do, walkin'|11into people's rooms like that?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1217, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6BDo you wanna have a jam session|11with me usin' that instrument?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1218, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Sorry, but try somethin' else.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1219, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|67Mikau?|11Where've you been? Where've you|11been? I was worried.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x121A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The concert in town is coming up,|11but it seems like all the band|11members are in a funk. I betcha|11didn't know that, huh?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x121B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Especially Lulu.|11I haven't heard her voice in a long|11time.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x121C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "She's usually in good spirits, too.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x121D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ooh! Ooh! I wonder if this is|11related to the ocean turning all|11weird...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x121E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|68Actually...|11I know a little bit of |01Lulu's|11secret|00.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x121F, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Do you wanna hear it?|11 |11|02|C2I wanna hear it|11Not really|BF", NULL);
    EZTR_Basic_ReplaceText(0x1220, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "There's a rumor that the ocean is|11getting weird 'cause there's|11trouble off shore at |01Great Bay|11Temple|00.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1221, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And they say when that happens,|11something bad will befall the |01Zora|11descendant|00 who's been protecting|11the temple.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1222, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Do you catch my drift?|11|13|13|12And lately, Lulu has been looking|11kind of weird. Maybe Lulu's the...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1223, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|67Oh, yeah, that's right. There aren't|11any secrets between you and Lulu.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1224, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ooh! Ooh!|11Don't tell Lulu that I've been|11saying stuff about her...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1225, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|68Um...|11Don't get mad, but I want you to|11hear this...|11|12I tried to climb up the other|11ladder to your practice area, and|11it broke. I'm gonna go on a diet|11now, so just forgive me, OK?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1226, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|67Ooh! Ooh!|11How's Lulu?|11Is she talking to you?|11|12Look...|11It's about Lulu's secret...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1227, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|67Huh? Who are you?|11You can't just come walkin' in|11here.|11|12I don't have a problem, but I think|11my roommate might get mad.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1228, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Just follow the rules if you're one|11of our fans.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1229, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|68This is a problem. You just can't|11come in and hang out in our|11room!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x122A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05|1E|68|45Can you read Zoran script?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x122B, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau|11My Diary|11|13|12Today, Japas and I had a jam|11session. He's not good with words,|11but he writes great riffs.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x122C, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17Here's what I played:|18|BF", NULL);
    EZTR_Basic_ReplaceText(0x122D, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Today, I had Lulu listen to my|11session with Japas.|11|13|12She seemed to like it a lot.|11Lulu's a pretty great girl,|11after all.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x122E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Today, I had another jam session|11with Japas.|11|13|12Evan was in a bad mood 'cause|11the two of us are writin' songs on|11our own.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x122F, 0x03, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17Here's what I played:|18|BF", NULL);
    EZTR_Basic_ReplaceText(0x1230, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Evan called me over this morning.|11It was something about Lulu.|11|13|12He was in a real rush. I wonder|11what it could be?|11|13|12By the way, it seems my lucky|11color this week is |02green|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1231, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau! How was it? Did you get|11the eggs back?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1232, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You did it, Mikau!|11|13|13|12OK...Take that egg straight to the|11professor at the Marine Research|11Lab.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1233, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I've already talked to the|11professor. Leave the rest up to|11him.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1234, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, thank goodness! Lulu's voice|11has been brought back to normal!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1235, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I've already talked to the|11professor, so after delivering the|11eggs, you can leave the rest up|11to him.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1236, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How was it? Did the professor at|11the Marine Research Lab figure|11out the mystery of the eggs?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1237, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh...|11You couldn't do it, after all.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1238, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Have you been to see Lulu out in|11back by the ocean?|11|13|12Ever since the pirates stole her|11eggs, she's just been standing out|11there gazing at the sea and|11sighing...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1239, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...Mikau!|11We need those eggs safe so Lulu|11can get her voice back.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x123A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We've grown accustomed to life|11in a peaceful sea...|11|13|12The only one among the Zora tribe|11who is still able to go to blows|11with those wild pirates...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x123B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It is you, with the blood of Zoran|11heroes flowing within you.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x123C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm still keeping Lulu's problem a|11secret from the other band|11members.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x123D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "They've all been looking forward to|11our Carnival of Time concert.|11|13|12And I can't tell them it's canceled|11'cause Lulu can't sing, can I?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x123E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Anyway, Mikau, did you get an|11|01empty bottle |00that you can use to|11carry the eggs in?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x123F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "One |01bottle|00 can only hold one |01egg|00,|11so you can never have too many|11|01empty bottles|00.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1240, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I told you that the |01beavers|00 above|11the|01 waterfall|00 on the Zora Hall|11coast have |01empty bottles|00, right?|11|12If you don't have any yet, Mikau,|11you should go there before|11heading off to the Pirates'|11Fortress.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1241, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The Carnival of Time concert is|11quickly approaching...|11|13|12Hurry up and get those eggs back|11from the pirates.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1242, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I already told you the beavers|11above the |01waterfall|00 have |01empty|11bottles|00, right?|11|12If you don't have any yet, you|11should go there before going to|11the Pirates' Fortress.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1243, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What is this?|11You can't just come into people's|11rooms and make yourself at home!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1244, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ahh...|11If Lulu's voice doesn't return,|11I don't know what we can do...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1245, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey!|11How did you get in here?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1246, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I shouldn't have to put up with|11this...People not associated with|11the band aren't allowed in here.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1247, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you want an autograph, we'll be|11giving them out at the town's|11carnival, so wait until then.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1248, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Were you guys secretly writing a|11song behind my back again?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1249, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Isn't songwriting the job of the|11bandleader? What, you're not|11happy with my songs?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x124A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I heard that song. If you write|11any other good songs, I'd like|11to hear them.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x124B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Huh?|11That song?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x124C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hmmm...|11|1F|00|04|17It works,|18 |1F|00|04|17it works,|18|11|1F|00|04|17it works!|18|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x124D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Not bad...|11|1F|00|0AThat's a pretty good song I just|11made up!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x124E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You've got a good sense of|11melody! We'll play my new song at|11our next show! Take this in|11thanks!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x124F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You're not thinking I'm stealing|11your song, do you? |E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1250, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you want an autograph, I'll give|11you one after our rehearsal.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1251, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What have you been doing? You're|11late, Mikau!|11|13|12Ooh! Ooh!|11Guess what! Lulu's voice...|11She's gotten it back!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1252, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hurry up and go see Lulu.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1253, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And with that, we're all ready.|11I can't wait for the town's|11concert.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1254, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We've kept you waiting! Just a|11little bit longer and we'll play our|11hot sound for you!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1255, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17You're late, Mikau! Where were|11you while you were skippin'|11practice?|18|11|12|1F|00|0ALulu's been waiting for you.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1256, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17What were you doing?|18|11|1F|00|14Hurry up and go talk to Lulu!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1257, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey, Mikau...|11|13|13|12That song Evan wrote sounds just|11like the one we played at our jam|11session, doesn't it?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1258, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I've written a great song, so just|11be patient.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1259, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You did great, Mikau.|11Lulu's voice |1F|00|0Ahas returned.|11|13|12Well, it looks like Lulu wants to|11talk to you, |1F|00|0A|17so go see her|11now.|18|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x125A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, hurry up!|11We're about to start rehearsal.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x125B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm glad I got this new song done|11in time for the concert.|11|13|12You did great, Mikau. And even|11without any practice.|11|13|12You really are a musical genius...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x125C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You're an unusual sight to see in|11this neck of the water...|11|13|12You came to see the Zora band,|11The Indigo-Go's, didn't you?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x125D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The members of The Indigo-Go's|11are in |01Zora Hall|00 up ahead...|11|13|12But the entrance is underwater,|11so if you aren't a good diver, you|11probably won't make it in.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x125E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The members of The Indigo-Go's|11are up ahead in |01Zora Hall|00...|11|13|12But if you can't dive deep|11underwater, you won't get in.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x125F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey, aren't you Mikau?|11Were you able to get an empty|11bottle from the beavers on top of|11the|01 waterfall|00?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1260, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Those guys are quick, so it's|11pretty tough, isn't it?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1261, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But what do you need an |01empty|11bottle|00 for, Mikau?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1262, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Can you |01break |00all those jars|11behind me in one try?|11|13|12Among us Zora, there are some|11who can.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1263, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you do it, I'll give you|11something good.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1264, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Anything's worth a try!|11Think it over and give it a shot.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1265, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey, Mikau...|11You wanna do that thing you used|11to always do?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1266, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You just can't play guitar all the|11time. You gotta get out and move|11your body once in a while.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1267, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Clock Town's carnival is coming|11soon and business there is good.|11That'd be nice...Things here aren't|11picking up yet.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1268, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We haven't been able to catch any|11fish in the ocean, so we have to|11go to town to buy them.|11|12We never had a need for |06Rupees|11|00until now.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1269, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I have a shop inside Zora Hall, so|11actually I'd like you to go there|11and buy a lot of stuff...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x126A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I don't want to sound greedy, but|11I need to make money for the|11jars.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x126B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We can't fish in the ocean|11anymore, so everyone's going into|11town to buy them instead.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x126C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But I just can't get used to the|11taste of fish from a river.|11|13|12But a Zora's gotta eat, so there's|11no way around it.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x126D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If your band does well with its|11concert in town, it'll bring tourists|11here and...|11|12I won't have to ask for jar money.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x126E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Way to go, Mikau!|11|13|13|12You've got a big smirk on your|11face...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x126F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, here's |06100 Rupees|00.|11|13|13|12Except...|11Jar replacement costs |0610 Rupees|00,|11so I'll have to deduct that.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1270, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You get |0690 Rupees|00!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1271, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Take the challenge again sometime.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1272, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Whoa!|11There are others besides Zoras|11who can do it...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1273, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What's wrong? Have you lost your|11touch from playing too much|11guitar, Mikau?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1274, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Didn't you used to be able to|11break all these pots at once?|11|13|12Your motion was all stiff like|11someone who's not used to doing|11this...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1275, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Sorry, but I have to take|11|0610 Rupees|00 for those broken jars.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1276, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey, that's a problem...Don't go|11breaking my jars. Those jars|11aren't free, you know.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1277, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What? You don't even have|11|0610 Rupees|00?|11|13|12I guess there's nothing I can do...|11I'll just have to eat the loss.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1278, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you break them all at once, I'll|11give you something good.|11|13|12Take the challenge again sometime.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1279, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This is the room of Mikau and|11Tijo, the guitarist and drummer for|11the Zora band, The Indigo-Go's.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x127A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "They don't meet with ordinary|11people.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x127B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "No way. If you want to meet|11Mikau and Tijo, you'll have to go|11through their manager.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x127C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey, Mikau...|11I haven't seen you in a while.|11Where have you been?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x127D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, that's right. Evan, your|11bandleader, is looking for you.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x127E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Evan came by several times|11looking for you. Have you seen|11him yet?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x127F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This is the room of Japas, bassist|11for the Zora band, The Indigo-Go's.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1280, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm sorry, but he's busy practicing|11for the concert, so I can't let you|11see him.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1281, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you're not a band member, you|11can't go in...Even if you're an|11acquaintance.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1282, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau...|11Do you need to see Japas?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1283, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You're gonna have another jam|11session with him, aren't you?|11I can't wait!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1284, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm expecting a cool performance|11in your jam session with Japas.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1285, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This is the room of Evan, the|11leader of the Zora Band, The|11Indigo-Go's.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1286, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "He's a nervous guy, so nobody's|11allowed inside unless they're on|11official business.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1287, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Unless you have official business,|11it's impossible to see him until|11after the concert.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1288, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ah! Mikau!|11What have you been doing this|11whole time?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1289, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Evan the bandleader has been|11waiting for you for a while now.|11Hurry! Go in! Go in!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x128A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Stop worrying the bandleader like|11you do...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x128B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Shut up! I'm busy.|11Don't talk to me!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x128C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Shut up. I'm busy right now...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x128D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ah! Mikau!|11You caught me!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x128E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Eee...I...uh...er, L-Lulu's been|11l-looking kinda weird lately...|11I was w-worried...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x128F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It's not like I was s-spying on|11her or anything...|11|13|12I-I'm not some k-kind of weirdo or|11some sorta slimy fish or anything.|11...Um, yeah.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1290, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Uh...I just r-remembered that I|11have somewhere to be...What time|11is it? Um, yeah. I hafta be there,|11like, now. Uhhh...See ya!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1291, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Did you come to see The|11Indigo-Go's rehearse, too?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1292, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "No?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1293, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Have you heard of The|11Indigo-Go's?|11|02|C2Of course|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x1294, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I thought so. The Indigo-Go's are|11pretty big now, aren't they?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1295, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Their rehearsal is about to begin,|11so I thought you came to see|11them.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1296, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But even though their concert in|11town is tomorrow, they still|11haven't started rehearsing.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1297, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I wonder what they're doing?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1298, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Huh? You don't know them?|11The Indigo-Go's is that popular|11band that's going to be doing a|11concert in town soon!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1299, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "They've got|01 Evan|00, the keyboard|11king, the thumping bass of |01Japas|00,|11the cool drum beat of |01Tijo|00...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x129A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But above all, |01Mikau|00's weeping|11guitar and the shimmering voice of|11|01Lulu |00make the best songs!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x129B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ah, you're Mikau, right? Good luck|11practicing for the concert!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x129C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm looking forward to your |11rehearsal.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x129D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Aren't you going to rehearse?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x129E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Or are you just gonna hit the|11stage without any practice?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x129F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hohhh!|11That's a real genius guitarist!|11So bold!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The stage lights turned on! The|11rehearsal's gotta start soon.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ahh...Lulu!|11Hurry up and show your face on|11stage!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Did you come here to see The|11Indigo-Go's 'cause you couldn't|11wait for the concert?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I heard they were having a|11rehearsal, and I've been waiting|11here ever since.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But the stage lights aren't even|11lit, so it looks like it'll be a while|11before rehearsals start.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I wonder when they're gonna|11start? C'mon, I want to see my|11Lulu.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ah! Mikau!|11Hey, what's Lulu doing now?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm so jealous of you! To always|11be able to breathe the same air|11as Lulu...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And you know a side of Lulu that|11I don't...You know her private side,|11don't you?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12A9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That's wonderful. I won't ask you|11to introduce me. A pictograph will|11do. Show me Lulu's private side.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12AA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Did you by chance bring something|11of Lulu's?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12AB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If it's about Lulu, I want to know|11everything. I'll take anything...You|11know? I'm the consummate fan!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12AC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hmmm...This isn't that great, but|11I'll buy it off you anyway.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12AD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Next time, bring me a better shot|11that really captures Lulu.|11If you do that...|11I'll do you no wrong.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12AE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh! Lulu's face.|11It's irresistible!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12AF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Please let me have this!|11OK? OK?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Keep the change.|11|13|13|12For this kind of pictograph, I'll|11take as many as you have, so|11bring more!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey, you can't do that. No|11climbing up on the rehearsal|11stage.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We're doin' the sound check right|11now, so don't make any noise.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hurry up and get off the stage.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau, you're just in time. I want|11to check the levels on your|11guitar.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Can you play me a note?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau, can you play me a quick|11note?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ack!|11That's a little too loud.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I guess I'll turn it down a bit...|11|13|13|12OK. Thanks, Mikau.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12B9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Huh?|11That's a little too quiet...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12BA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I guess I'll turn it up a bit...|11|13|13|12OK. Thanks, Mikau.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12BB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Wha? They're off again. That's a|11problem...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12BC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Are you free? If you have a sec,|11could you go light the second|11floor's seating lights?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12BD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Unless those are on, the stage|11lights won't come on.|11Thanks.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12BE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Are you the one who turned those|11lights on?|11|13|12You saved me.|11Here...Go buy whatever you like!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12BF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "All right...The lights are all good.|11Now we just have to wait...|11But they'll probably go out |11again pretty soon...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12C0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What do you want, Mikau?|11Are you checking the stage?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12C1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I don't know why, but there's|11something wrong with the|11lighting...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12C2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The lighting isn't working right.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12C3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau...|11How do you like it? The lights are|11perfect.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12C4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Now hurry up and do start your|11rehearsal before the lights go out.|11Hurry! Hurry!|E0|BF", NULL);
