    EZTR_Basic_ReplaceText(0x12C6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Huh? Here too? This is a problem.|11Rehearsal hasn't started yet, so I|11guess it's OK, but...|19|BF", NULL);
