    EZTR_Basic_ReplaceText(0x12C9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Once the rehearsal starts, you'll|11have to buy a ticket. You just|11can't go and take a seat.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12CA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oy! Mikau! What's up with the|11rehearsal?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12CB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I've been told that rehearsal is|11about to begin...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12CC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But the band members are still|11shut away in their rooms...|11|13|12And Lulu's just hanging around by|11that lone island out back.|11What's going on?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12CD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Is Lulu all right? She was just|11staring out at the lone island in|11back...She looks kinda strange.|E0|BF", NULL);
