    EZTR_Basic_ReplaceText(0x12D1, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Didn't the big guy's shop have|11what you were looking for?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12D2, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Welcome.|19|BF", NULL);
