    EZTR_Basic_ReplaceText(0x12D6, 0x06, 0x31, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "View products by moving |BB left|11or right.|11|02|C2Speak to shopkeeper|11Quit shopping|BF", NULL);
    EZTR_Basic_ReplaceText(0x12D7, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You came to see The Indigo-Go's,|11too, didn't you?|11I can tell.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12D8, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The celebrities' dressing rooms are|11near here. Maybe you can take a|11peek...|11Just don't get caught.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12D9, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Lately, I've had a hard time even|11getting fish in stock, so this is|11all I have.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12DA, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Your band's popularity is amazing.|11We've had all kinds of people|11coming into the shop lately.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12DB, 0x06, 0x30, 0xFE, 0xFFFF, 0x005A, 0xFFFF, true, "|01Hero's Shield: 90 Rupees|11|00This is the shield that heroes|11use, but it doesn't sell very well|11here.|1A|BF", NULL);
    EZTR_Basic_ReplaceText(0x12DC, 0x06, 0x31, 0xFE, 0xFFFF, 0x005A, 0xFFFF, true, "Hero's Shield: 90 Rupees|11 |11|02|C2I'll buy it|11No thanks|BF", NULL);
    EZTR_Basic_ReplaceText(0x12DD, 0x06, 0x30, 0xFE, 0xFFFF, 0x0014, 0xFFFF, true, "|0110 Arrows: 20 Rupees|11|00These fly well when shot from a|11bow, and you need one if you|11want to buy any of these.|1A|BF", NULL);
    EZTR_Basic_ReplaceText(0x12DE, 0x06, 0x31, 0xFE, 0xFFFF, 0x0014, 0xFFFF, true, "10 Arrows: 20 Rupees|11 |11|02|C2I'll buy it|11No thanks|BF", NULL);
    EZTR_Basic_ReplaceText(0x12DF, 0x06, 0x30, 0xFE, 0xFFFF, 0x003C, 0xFFFF, true, "|01Red Potion: 60 Rupees|11|00Drink this when your energy is|11low to ease your weariness.|1A|BF", NULL);
    EZTR_Basic_ReplaceText(0x12E0, 0x06, 0x31, 0xFE, 0xFFFF, 0x003C, 0xFFFF, true, "Red Potion: 60 Rupees|11 |11|02|C2I'll buy it|11No thanks|BF", NULL);
    EZTR_Basic_ReplaceText(0x12E3, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You can't hold anymore.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12E4, 0x06, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You don't have an empty bottle to|11put it in...|E0|BF", NULL);
