    EZTR_Basic_ReplaceText(0x12E8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau, haven't you seen any|11|01gold-colored fish |00around here?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12E9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|01Gold-colored fish|00 know this area|11very well.|11|13|12I was thinking of getting one to|11guide me to |01Pinnacle Rock|00...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12EA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If the water wasn't so murky,|11I wouldn't have to rely on the|11guidance from a |01gold-colored fish|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12EB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I heard that the pirates were|11attacked by sea snakes near the|11creatures' lair.|11|12It seems they dropped |01something|11precious |00there. Don't you wonder|11what it was, Mikau?|11|12But we'd have to get through that|11murky water to look for it...|11|13|12Where are all the |01gold-colored|11fish |00when we need them?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12EC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Yo, Mikau!|11The seawater has gradually|11returned to normal.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12ED, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But that weird, murky water hasn't|11dissipated completely...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12EE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Before long, the fish will come|11back, too!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12EF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Are you taking a relaxing sea|11bath? Isn't the water here too|11warm for it to feel good?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Plus, with all this murky water|11around, you'd better be careful!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Can't you go for a nice swim now|11that the water temperature has|11gone down?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F2, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How is it?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ah! Mikau!|11What are you doing in a place like|11this?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This is the ominous |01Pirates'|11Fortress|00. I don't think you should|11get too close.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Uh...But I'm OK...|1F|00|28|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, actually...|11|13|13|12The pirates in this fortress are|11all women. And better yet, I hear|11they're all gorgeous.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Heh, heh...So, I thought maybe|11I should check 'em out.|11|13|12What??|11Don't look at me like that...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The Pirates' Fortress usually is|11closed off by an iron gate, so you|11can't get in from here.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12F9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And even if you did get in, it's|11not like the pirates would welcome|11you.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x12FA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Yo, Mikau!|11Did you do something to the|11pirates?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12FB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The pirates were just looking for|11a Zora dressed in|02 green clothing|00.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12FC, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Isn't that you?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12FD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "It sounded like the pirates had|11some unfinished business to settle|11with you...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12FE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Did you do something?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x12FF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Is this your first time at the|11ocean? This is the ominous|11Pirates' Fortress.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x1300, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you hang around too long, the|11pirates will see you and get you.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1301, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you came here to go swimming,|11you should go somewhere else.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1302, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau! What are you doing?|11Everyone's already up on stage.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1303, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The Indigo-Go's will start|11rehearsing soon.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1304, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau! Man, you're guitar playing|11is the best!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1305, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How'd you like The Indigo-Go's?|11Aren't they the best?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1306, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How do you feel, Mikau? We can't|11wait to hear you!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1307, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm so excited...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1308, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Yeah! Mikau, isn't Lulu's singing|11the greatest?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x1309, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey! Did you hear that? This|11guarantees the concert in town|11is gonna be a huge success.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x130A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Late, Mikau?|11Hurry up and get on stage.|E0|BF", NULL);
