    EZTR_Basic_ReplaceText(0x130C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau!|11That new song has a nice feel to|11it. I really like it.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x130D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What d'ya think?|11Doesn't the new song by The|11Indigo-Go's sound great?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x130E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Mikau!!!|11Hurry...Make your guitar gently|11weep for me!|E0|BF", NULL);
