    EZTR_Basic_ReplaceText(0x1945, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05That's a |00Gekko|05.|11And it's pretty angry!|11It's pretty weak, too. It really|11shouldn't be making a fool of you.|BF", NULL);
