    EZTR_Basic_ReplaceText(0x1947, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05You know about the |00Leever|05, right?|11It actually moves pretty fast.|11That's not exactly good news,|11is it?|BF", NULL);
