    EZTR_Basic_ReplaceText(0x1949, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Pea Hat Larva|05...You don't know|11about it? If it comes at you, get|11in the defensive position to knock|11it back!|BF", NULL);
    EZTR_Basic_ReplaceText(0x194A, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05It's an |00Eyegore|05.|11Simply attacking it is no good.|11I say you should pay attention to|11the subtle changes in its eye.|BF", NULL);
    EZTR_Basic_ReplaceText(0x194B, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05It's a |00Wizrobe|05.|11You'll get your chance right when|11it starts to attack. Be on the|11lookout for it!|BF", NULL);
    EZTR_Basic_ReplaceText(0x194C, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05So you don't know about the|11|00Wolfos|05? Lure it in and watch its|11movements. It doesn't like its tail|11to be touched...|BF", NULL);
    EZTR_Basic_ReplaceText(0x194D, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05That's one |00Mad Scrub|05!|11Even though it's weak, it sure|11likes to attack!|BF", NULL);
