    EZTR_Basic_ReplaceText(0x1952, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05It's |00Beth|05, third of the four ghost|11sisters. Aim when she appears!|11Hurry up! There are still more!|BF", NULL);
    EZTR_Basic_ReplaceText(0x1953, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05It's |00Amy|05, youngest of the four|11ghost sisters. Target her when|11she appears! You got that?|BF", NULL);
    EZTR_Basic_ReplaceText(0x1954, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05The |00pirate|05 found you!|11Use Z targeting and look for your|11chance. You're caught if you don't|11win.|BF", NULL);
