    EZTR_Basic_ReplaceText(0x1956, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05You know about the |00Ice Keese|05,|11right? Destroy it before it|11swoops down on you. I hate the|11c-c-cold!|BF", NULL);
