    EZTR_Basic_ReplaceText(0x1958, 0x08, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05It's a |00Guay|05. You don't know about|11this one? Just attack it before it|11swoops down on you. That's|11all there is to it.|BF", NULL);
