    EZTR_Basic_ReplaceText(0x2366, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I saw him somewhere...|11It was somewhere around here...|11|13|12Sorry, I'm busy.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2367, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ohh, how many people are gonna|11ask me that? That lady is so|11persistent.|11|12Soooo, doesn't Kafei want to|11break off his engagement to|11Anju? Why not let him? That's|11what he wants... |10Some people...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2368, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You're the one my wife has hired?|11So Kafei still hasn't...hmmm.|11|13|12This is a secret, so don't tell|11my wife.|11|13|12Go ask at the Curiosity Shop, the|11store in the west part of town|11that only opens at night. That|11guy is a bad influence on me...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2369, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...I don't know where he is.|11Even if I knew, it would be a|11secret.|BF", NULL);
    EZTR_Basic_ReplaceText(0x236A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|46Kafei?|11|13|13|12I can recall when he was in the|11Bombers.|11|13|12Don't see his face much anymore,|11though...Well, what could he be|11doing?|11|12Try asking the children. The|11Bombers know all about what goes|11on in town.|BF", NULL);
    EZTR_Basic_ReplaceText(0x236B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I used to see him at the Laundry|11Pool a lot.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x236C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|00What? Oh, a mask?|11I've seen a real Keaton near the|11slide!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x236D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Act your age!|11Don't be a crybaby!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x236E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|02.........???|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x236F, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You can't aim for the targets|11when you're wearin' a mask, sonny.|11Take it off.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2370, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ah, Kafei, eh?|11He hasn't come here.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2371, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Eeesh! You can't aim for the|11targets wearin' somethin' like that|11monstrosity on your head, sonny.|11Take it off.|BF", NULL);
