    EZTR_Basic_ReplaceText(0x2373, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "C'mon! Play the game wi'out|11wearin' a mask like that!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2374, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I don' know that kid.|11Nevah seen 'im b'foah in me|11life.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2375, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4BAye, Congratulations!|11Who's gettin' married?|11Awn't they gonna 'ave a big|11ceremony?|BF", NULL);
