    EZTR_Basic_ReplaceText(0x2377, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4CC'mon! Play the game wi'out|11wearin' a mask like that! Yoiks!|BF", NULL);
