    EZTR_Basic_ReplaceText(0x2710, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This training center has friendly,|11polite, 24-hour, one-on-one training|11that will noticably improve your|11sword skills!|10From now until the end of the|11carnival, join at a special|11discount.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2711, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "From now until the end of the|11carnival, join at a special|11discount.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2712, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "When you sharpen your sword|11skills, your mind is sharpened|11naturally.|11|12With the moon getting closer in|11recent days, the number of the|11weak and frightened has|11increased.|10But when you attain a master's|11level of training as I have, there|11is nothing to fear!|11|12By learning at this training center,|11you too can attain such a strong|11mind and will.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2713, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "When you sharpen the sword|11skills, your mind is sharpened|11naturally.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2714, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Rumors are spreading which|11suggest the moon is falling, but|11you can breathe easier as long as|11I am in town.|10Tonight, I shall cut the moon into|11pieces! If one does not have such|11skill, he cannot teach the way of|11the sword to others.|10If you wish to be as powerful as I|11am, then I shall teach you until|11nighttime.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2715, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you wish to be as strong as I|11am, then, until nighttime, I shall|11teach you many lessons in the|11way of the sword.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2716, 0x06, 0x01, 0xFE, 0xFFFF, 0x0001, 0x000A, true, "So, will you try it?|11|13|13|12|02|C3Novice Course |061 Rupee|11|02Expert Course |0610 Rupees|11|02No thanks|BF", NULL);
    EZTR_Basic_ReplaceText(0x2717, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Is that so? Regrettable.|11Truly regrettable.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2718, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5BYou don't have enough |06Rupees|00 to|11take that course!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2719, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5AHmm...The |01Novice Course|00!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x271A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Now then, before you draw your|11sword, I shall teach you the|11basics of |01unarmed|00 combat.|11|12I'll start with |01sideways jumps|00.|11After pressing |B5 to lock onto|11that log with Z-Targeting, press|11|B0 while pushing |BB left or right.|10Try it yourself.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x271B, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|01Jump sideways |00by pressing |B0|11while pushing |BB left or right|11after you have used |B5 to|11target something.|10Try it once more!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x271C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Next is the |01roll attack|00.|11After pressing |B5 to Z-Target,|11press |B0 while pushing |BB|11forward to roll.|10Begin!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x271D, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "After Z-Targeting with |B5, press|11|B0 while pressing |BB up to move|11and perform a |01roll attack|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x271E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Next is the |01backflip|00.|11Lock on and Z-Target the log with|11|B5, then press |B0 while pushing|11|BB down to jump.|10Begin!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x271F, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Perform the |01backflip|00 by pressing|11|B0 while pushing |BB down after|11you've locked onto your target|11with |B5.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2720, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "All right, now think of that log as|11an enemy and practice your sword|11skills!|11|12First is the |01horizontal cut|00.|11Simply press |B1.|11Now then...|11Begin!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2721, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Just press |B1 for a |01horizontal|11cut|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2722, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Next is the |01vertical cut|00.|11Press |B1 after Z-Targeting with|11|B5.|11Now then...Begin!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2723, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Press |B1 after Z-Targeting with|11|B5 to execute a |01vertical cut|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2724, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Next is the |01thrust|00.|11After pressing |B5 to Z-Target,|11push |BB forward and press |B1.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2725, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "After Z-Targeting with |B5, push|11|BB forward and press |B1 to|11perform a |01thrust|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2726, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And finally, the |01jump attack|00.|11Press |B0 after drawing your|11sword and Z-Targeting with |B5.|11Begin.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2727, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Draw your sword, press |B5 to|11Z-Target, then press |B0 to|11perform the |01jump attack|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2728, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5AWell done!|11Do not forget what I have taught|11you thus far and do not neglect|11your daily practice!|10Ah, yes, you can press |B4 to|11defend yourself with your shield.|11Did you know that?|BF", NULL);
    EZTR_Basic_ReplaceText(0x2729, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5BWrong!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x272A, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You must release |B5 and press|11|B0 to put away your sword!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x272B, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Do not Z-Target!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x272C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5B|17Fool!|18|11What can I teach to one who has|11no sword?!?|BF", NULL);
    EZTR_Basic_ReplaceText(0x272D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...Hmmm. Impressive.|11I must give you something.|11|1F|00|0AHere!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x272E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Your training is insufficient. You|11must jump more!|11|13|12Start over from the beginning.|BF", NULL);
    EZTR_Basic_ReplaceText(0x272F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Unbelievable...|11Cherish it well...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2730, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|80What? Have you some kind of|11complaint?|BF", NULL);
    EZTR_Basic_ReplaceText(0x2731, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This is a training center for|11learning the sacred way of the|11sword. It is no place for children!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2732, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5BThis is a place for studying the|11way of the sword. It is no place|11for children to play!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2733, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you wish to study the way of|11the sword at this training center,|11come after you've become an|11adult.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2734, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5CUmm...Excuse me, but this is a|11training center for studying the|11way of the sword...|11|12I can't help those without a|11sword.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2735, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5CThis training center is for|11studying the lowly sword...It is no|11place for one of your stature, sir.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2736, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5CHere...those who have no sword...|11cannot...I'm sorry, but it's the|11regulations.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2737, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "How unfortunate it is, since you|11seem to have good skill, but this|11is a center for studying the way|11of the sword.|10If you don't have one...|11But if you have a friend who|11wants to study, tell them we have|11a special discount going on.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2738, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Regrettable. If only you had a|11sword, you could become a sword|11master, like myself...|11|12And it's even a bargain now with|11our special discount...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2739, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "At my training center, you could|11become a master right away...|11|13|12Too bad you have no sword.|BF", NULL);
    EZTR_Basic_ReplaceText(0x273A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5AThe |01Expert Course|00 is a practice|11session!|11|13|12Cut down the |0110|00 logs using the|11highly difficult techniques!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x273B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "If you score a perfect |0130 points|00,|11you shall be taught all the|11secrets!|11|12Have you prepared?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x273C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Uuuuurgh...I'm scared!|11I can't take it!|11I don't want to die!|BF", NULL);
    EZTR_Basic_ReplaceText(0x273D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5BThis is a training center for the|11sacred sword!|11What is that mask?|11|12Is that the manner of one who|11wishes to study the sword?!|11Come when you are ready!|BF", NULL);
    EZTR_Basic_ReplaceText(0x273E, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I do not know that child.|BF", NULL);
    EZTR_Basic_ReplaceText(0x273F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5B|17Why do you wear the|11|01All-Night Mask|00?|18|11|13|12Are you suggesting that my |11instructions will put you to sleep?|11How rude! Be gone!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2740, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17Ohh, how adorable!|18|11Let me tug on your long ears...|11|13|12Ahem...If you study the way of|11the sword here, you'll get your|11bunny dirty, so put it away.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2741, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, ".........|11|13|13|12|1E|69|5CThis is a training center for|11studying the way of the sword, so|11I will teach anyone who has a|11sword... |10But first, leave that mask at|11home...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2742, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Why do you wear a ninja's mask?|11Do you wish to become a ninja in|11the future?|11|12How nice. The innocence of|11children...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2743, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "......|11|1E|69|5C Do you really wish to study the|11sword?|11|12I can't find the will to teach you|11when their milk has no freshness...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2744, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This is a training center for|11studying the sacred sword!|11Why that mask? How ugly and|11sorrowful.|10If you wish to study the sword,|11first remove that strange|11plaything.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2745, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ahh...You always do a wonderful job|11delivering the mail.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2746, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, congratulations.|11Did a friend get married?|11Mmm...To be young...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2747, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17Hey, that's not bad. That girl's|11mask is very beautiful!|18 I'll lose my|11focus if I try to instruct you|11while you're wearing that.|10Leave it at home.|11Or...I could keep it for you.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2748, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17Frightening! That mask!|11It's frightening!!!|18|11|13|12That scares me.|11Take it off! Take it off!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2749, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm no good at singing, so I won't|11sing. Not even if you wear that!|BF", NULL);
    EZTR_Basic_ReplaceText(0x274A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "......|11Why that mask?|11Are you making fun of me? If|11you're making fun of me, be gone!|BF", NULL);
    EZTR_Basic_ReplaceText(0x274B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17Waaah!|18|11|13|13|12If you wish to study the way of|11the sword, remove that mask! It|11looks like something I saw in a |11bad dream...|BF", NULL);
    EZTR_Basic_ReplaceText(0x274C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hmm?|11...Is someone there???|BF", NULL);
    EZTR_Basic_ReplaceText(0x274D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5BThis is a training center for the|11sacred sword!|11|13|12Do not wear that mask and march|11around in here! If you wish to do|11that, go outside!|BF", NULL);
    EZTR_Basic_ReplaceText(0x274E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5BThis is a training center for|11teaching the sacred sword!|11Why do you wear that mask?|11|12I cannot allow such an evil weapon|11in here. Come back when you are|11ready!|BF", NULL);
    EZTR_Basic_ReplaceText(0x274F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|5BThis is the training center of the|11sacred sword! Why do you wear|11that mask?|11|12I am not stinky!|11|17I take a bath at least once a|11month!|18|BF", NULL);
    EZTR_Basic_ReplaceText(0x2774, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6FI'm currently on the job.|11If I stop to talk, it will disrupt my|11schedule.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2775, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6FAccording to my schedule, it is|11now my nap time.|11|13|12If my schedule is disrupted by|11even a few seconds, letter|11delivery will be delayed...|11Public service is very hard.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2776, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, true, "|BF", NULL);
    EZTR_Basic_ReplaceText(0x2777, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This is a problem...A real problem.|11Not a single letter was mailed...|11|13|12What should I do this afternoon...|11I wish someone would tell me.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2778, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, true, "|BF", NULL);
    EZTR_Basic_ReplaceText(0x2779, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...You're disrupting me!|BF", NULL);
    EZTR_Basic_ReplaceText(0x277A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Last night, I wrote a letter to|11myself and deposited it in a post|11box...|11|12I just retrieved it. This afternoon,|11I shall deliver that letter!|11Hrr, hrr!|BF", NULL);
    EZTR_Basic_ReplaceText(0x277B, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6FTo Myself,|11You have been doing a great job|11delivering the mail.|11|12I have a request for my|11hard-working self. All of the|11townsfolk have taken refuge.|11I want myself to flee, too.|10Even if it is not written on the|11schedule, I want myself to flee.|11Please...|11                  From Me|BF", NULL);
    EZTR_Basic_ReplaceText(0x277C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ohhh...I want to flee!|11B-but, it's not written on the|11schedule.|11|12T-to me, the delivery schedule...|11It's the h-highest priority.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x277D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "T-to me, the delivery schedule...|11It's the h-highest priority.|BF", NULL);
    EZTR_Basic_ReplaceText(0x277E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Th-this is a priority mail seal!|11This is the highest of priorities.|11I shall deliver it!|BF", NULL);
