    EZTR_Basic_ReplaceText(0x28D1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|25You're also looking for Kafei?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28D2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I have a request!|11Kafei...I have a clue...that will help|11you find him.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28D3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Tonight at |0111:30|00, please come to|11our |01kitchen|00.|11We'll talk then...|BF", NULL);
    EZTR_Basic_ReplaceText(0x28D4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I will try to find him myself.|11Asking someone else to do it...|11I can't do that!|BF", NULL);
    EZTR_Basic_ReplaceText(0x28D5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|24I can't find him...|11Kafei...|11|13|12Where...|11I wonder where he could have|11gone...|11|12And there's only a little time left|11before...|11our wedding...|BF", NULL);
    EZTR_Basic_ReplaceText(0x28D6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|25Ah! ...Umm...Never mind!|BF", NULL);
    EZTR_Basic_ReplaceText(0x28D7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I am sorry to trouble you late at|11night. It's about him...Kafei.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28D8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I received a letter from...him.|11|13|13|12Strange...Isn't it?|11Getting a letter from a missing|11person...|11|12But there's absolutely no mistaking|11it's from him!|11|13|12It's clear...to me...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28D9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Please!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28DA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Here is my letter.|11Please put this in a postbox.|11|13|12When this is delivered...When he|11receives my letter... You should be|11able to |01meet |00him!|11|12Please tell him that Anju is|11waiting for him.|11|13|12And please, after you've seen|11him...|11Tell me how he looked.|11|12I'm scared...I...I can't go.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28DB, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Can I ask this of you?|11 |11|02|C2Yes|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x28DC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Thank you...very much.|BF", NULL);
    EZTR_Basic_ReplaceText(0x28DE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Please mail it immediately in the|11|01morning|00.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x28DF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|22...Uh, umm...Aren't you going to|11take refuge?|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|22...Ah...Today's weather is|11unfortunate, isn't it?|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I have decided to wait for him.|11I've made my promise...|11|13|12I'm fine with this.|11I believe him.|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|22Oh...|11|13|13|12Did you...see him?|11|13|13|12...I'm sorry. It's too late, isn't it?|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|22Oh...|11|13|13|12Did you...see him?|11|13|13|12...I'm sorry.|11It's probably too soon to ask...|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|22Oh...|11|13|13|12Did you meet him?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E5, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|25Ah!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...It's from Kafei.|11Th...Th...Thank you...|11Very much!|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|23Umm...What's that?|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Excuse me.|11Have you seen a man in this|11area?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28E9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "He looks like this...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28EA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "He...disappeared about one month|11ago with his |01wedding ceremony|11mask|00.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28EB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm...actually...afraid to meet him...|11|13|13|12and to hear the reason why he|11wanted to disappear...|11|13|12It might be because of... me...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28EC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "There are only |01two days |00until the|11carnival...|11Should I wait?|11Kafei...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x28ED, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|25Ah! That mask...|11You're looking for him, too.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28EE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I came here thinking I would look|11for him myself, but...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28EF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05|1E|68|45What a ramshackle inn. Is this|11room first-class? You can hear|11whoever's next door for cryin' out|11loud!|10Well, whatever...We're staying for|11free, so we can't expect much.|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|05|1E|68|45See, everything here is falling|11apart...You can hear the voices|11next door.|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "OK, Anju, we're leaving in the|11|01evening |00for the ranch.|11|13|12|01Cremia|00 will take us in. She is|11your best friend, right?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I wonder if Kafei is really at|11|01Cremia's|00 place...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|11If Kafei is there, your mother will|11give him a smack.|11|13|12|1F|00|0ABesides, think about Cremia. She|11needs strength from a partner and|11business support from Madame|11Aroma.|10If Kafei really has run off with|11Cremia, she'll get both. Please|11don't be sad. How happy could |11you possibly be...|10marrying a man who runs off|11when he's about to be married?|11It would make your life unhappy|11...just like your mother's.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But in the letter it said he |11definitely would come back...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|10Come back to what??|11Won't this town be crushed|11beneath the moon the morning|11after tomorrow?|10Forget about that letter. For now,|11just try to survive.|11|1F|00|0AEverything else will follow...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Yes...|11Mother, |1F|00|0AThank you.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Everyone will be taking refuge|11first thing in the morning. |11Everything was supposed to be all|11so...spirited...It's sad.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F8, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We'll be going to Romani Ranch in|11the evening to take refuge. I think|11you should all hurry too.|BF", NULL);
    EZTR_Basic_ReplaceText(0x28F9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Perhaps I was wrong...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28FA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But he said so...|11The morning of the ceremony...|11He'd come meet me in my room...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28FB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "And I promised him I would wait...|11|1F|00|0ABut...already...it's too late, isn't it?|BF", NULL);
    EZTR_Basic_ReplaceText(0x28FC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Anju stayed in her room to wait|11for Kafei...|11|13|12It's foolish |1F|00|0Ato believe a man|11like that.|11|13|12I too believed my husband would|11return out of the blue...|11|13|12Oh, Anju...|11That child's naive sense of trust|11may be my fault.|BF", NULL);
    EZTR_Basic_ReplaceText(0x28FD, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "!!!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x28FE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...I've been a little harsh on Anju.|11...But, it's fine this way.|11|13|12Right now, surviving is the|11important thing.|BF", NULL);
    EZTR_Basic_ReplaceText(0x28FF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm sorry.|11We're going to be taking refuge in|11the evening like the others.|11|12You should run, too.|11It seems it's going to fall|11tomorrow morning.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2900, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm sorry.|11Our rooms are filled.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2901, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0COh, Tortus, you're late...|11|13|13|12Tomorrow is another early day, so|11good night. I'll read you a story|11tomorrow.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2902, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0COh, Tortus.|11Did you finish helping father?|11|13|12Then let mother read you a story.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2903, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Now, which story would you like|11to hear?|11|13|12|02|C3I'll pass|11Carnival of Time |01 (2 hours)|11|02Four Giants |01(Til morning)|BF", NULL);
    EZTR_Basic_ReplaceText(0x2904, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The Carnival of Time, is it?|11|13|13|12The carnival is almost here, so it's|11good for you to learn its meaning.|11It's a little long, but I'll read it|11with some enthusiasm. Ahem...|10\"The Carnival of Time.\"|11Each year, the season of harmony|11begins when the sun and moon|11are in alignment.|10Paying homage to the way that|11both nature and time are|11tirelessly in the process of |11progressing...|10the Carnival of Time is when the|11peoples of the four worlds|11celebrate that harmony and|11request fruitfulness for the year.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2905, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "For ages, people have worn masks|11resembling the giants who are the|11gods of the four worlds.|11|12Now, it has become a custom for|11each person to bring a handmade|11mask to the Carnival of Time.|11|12It is said that if a couple united|11on the day of the festival and|11dedicated a mask as a sign of|11their union, it would bring luck.|10The centerpiece of the carnival is|11the clock tower, and on the eve|11of all the festivities, the doors to|11its roof are opened...|10From atop the clock tower roof, a|11ceremony to call the gods is held|11and an ancient song is sung.|11|12All of these festivities for the|11Carnival of Time are held so that|11we may ask the gods for a rich|11harvest in the year to come!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2906, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0AYou did a good job!|11That's all for Tortus!|11|13|12Now, when does the clock tower|11roof open?|11|02|C2On the eve of the festival|11I dunno|BF", NULL);
    EZTR_Basic_ReplaceText(0x2907, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0AWell in that case, you try again|11with mother.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2908, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0AYou did a good job remembering.|11That's the boy I'm proud of.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2909, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'll give you some candy as a|11prize.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x290A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0AOh, are you awake?|11|13|13|12I guess that story was a little|11boring for Tortus, wasn't it?|11|13|12Don't give up. Try again sometime.|BF", NULL);
    EZTR_Basic_ReplaceText(0x290B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|01The Four Giants|00, is it?|11|13|13|12This is quite long, but it is a good|11story for you to hear, so I'll read|11it with some extra gusto.|11Ahem...|10\"The Four Giants.\"|11This tale's from long ago when all|11the people weren't separated into|11four worlds like they are now.|10In those times all the people lived|11together, and the four giants lived|11among them.|11|12On the day of the festival that|11celebrates the harvest, the giants|11spoke to the people...|11|12\"We have chosen to guard the|11people while we sleep...\"|11|13|12\"100 steps north,|11100 steps south,|11100 steps east,|11100 steps west.\"|10\"If you have need, call us in a|11loud voice by declaring something|11such as, 'The mountain blizzard|11has trapped us.'\"|10\"Or 'The ocean is about to|11swallow us.' Your cries shall carry|11to us...\"|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x290C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Now then...There was one who|11was shocked and saddened by|11all this.|11|12A little imp.|11|13|13|12The imp was a friend of the|11giants since before they had|11created the four worlds.|11|12\"Why must you leave?\"|11 |11\"Why do you not stay?\"|11|12The childhood friend felt|11neglected, so he spread his anger|11across the four worlds.|11Repeatedly, he wronged all people.|10Overwhelmed with misfortune, the|11people sang the song of prayer to|11the giants who lived in each of|11the four compass directions.|10The giants heard their cry and|11responded with a roar.|11\"Oh, imp. Oh, imp. We are the|11protectors of the people.\"|10\"You have caused the people pain.|11Oh, imp, leave these four worlds!|11Otherwise, we shall tear you|11apart!\"|10The imp was frightened and|11saddened.|11 |11He had lost his old friends.|10The imp returned to the heavens,|11and harmony was restored to the|11four worlds.|11|12And the people rejoiced and they|11worshiped the giants of the four|11worlds like gods. And they lived|11happily...ever after...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x290D, 0x00, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0AGood job! Wasn't that fun,|11Tortus?|11|13|12What did the people do to call the|11giants?|11|02|C2Sing a song|11I dunno|BF", NULL);
    EZTR_Basic_ReplaceText(0x290E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0AOh, really?|11But you listened hard, so mother|11is happy.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x290F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'll give you some candy as your|11prize.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2910, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "That's right, but you couldn't just|11sing that song anywhere.|11|13|12100 steps north,|11100 steps south,|11100 steps east,|11100 steps west.|10The spot at which those giants|11parted is right in the middle of|11this very town.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2911, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0AOh, are you awake?|11|13|13|12I guess that story was a little|11hard for Tortus.|11|13|12But don't give up. Try again later.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2912, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0COh, Tortus, are you ready?|11|13|13|12It's been a long time since we've|11had a picnic at Romani Ranch,|11hasn't it?|BF", NULL);
    EZTR_Basic_ReplaceText(0x2913, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Isn't her bridal dress lovely?|11|13|13|12We promised each other when we|11were children that we'd marry on|11the day of the Carnival of Time.|11|12...|1F|00|0ABut my promise...|11|1F|00|0AI couldn't keep it.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2914, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I...I have met you before.|11|13|13|12What a familiar scent. Long, long|11ago...Yes. We were still young.|11We made a promise...|11Didn't we?|10The masks of the sun and the|11moon...|11|13|12We were to exchange them on the|11day of the Carnival of Time...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2915, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Anju...|11I'm sorry I was late.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2916, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...|1F|00|0AWelcome home.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2917, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|68|46|05...Tee-hee! |1F|00|0AThey're lovers, but they|11look just like a mother and child.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2918, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Let us exchange the promised|11masks.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2919, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We have exchanged our oaths and|11have become a |01couple|00.|BF", NULL);
    EZTR_Basic_ReplaceText(0x291A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You are our witnesses.|11Please accept this |01mask|00.|BF", NULL);
    EZTR_Basic_ReplaceText(0x291B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Please take refuge.|11We are fine here.|11|13|12We shall greet the morning...|11together.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x291C, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1CHmmm...Ah, well, that won't work...|11No...That's too basic... |E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x291D, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1EWe have to be ready without any|11rehearsal this time...Every time...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x291E, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1CWe need a new step...Maybe with|11more jumping...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x291F, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1EMarilla likes this choreography,|11but she doesn't get into it at all...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2920, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1CJudo's very good at it...|11Maybe we should add some|11spins...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2921, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1EIf we do a poor job of extending|11it, the audience will get bored...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2922, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1CMaybe I'll blame it on the troupe|11leader and go back to the village...|11But Judo wouldn't like it.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2923, 0x02, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1EWe shouldn't change the song|11now...Guru-Guru is scary when he|11gets mad...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2924, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We're pretty prepared, but our|11troupe leader seems to be acting|11strange for some reason.|11Well, we haven't even seen the|10stage yet...It looks like we're going|11straight to the big show without|11any rehearsal.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2925, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1DMaster!|11Please come to our performance!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2926, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|20Don't bother us!!!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2927, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Thank you for teaching us those|11steps.|15|BF", NULL);
    EZTR_Basic_ReplaceText(0x2928, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|1FYou are our master!|BF", NULL);
