    EZTR_Basic_ReplaceText(0x2941, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|57They're twins just like us! Can|11you believe it? I think they're|11practicing somewhere in West|11Clock Town right now.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2942, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "There are two sets of twins|11traveling in Gorman's troupe of|11entertainers! I mean, what are the|11chances?|19|BF", NULL);
