    EZTR_Basic_ReplaceText(0x2944, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|56Would you like to join our |11little card game?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2945, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You're joking, aren't you, brother?|11He'll make our game too complex!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2946, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What ever do you mean?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2947, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|56It's easy playing against you!|11You look just like me, so I already|11know what you look like when|11you're bluffing!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2948, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|74Pa-Pa-Pa-Paper, please!|19|BF", NULL);
