    EZTR_Basic_ReplaceText(0x294B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Ho!|11|1F|00|0AYou saved me...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x294C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This fell down here...|11I'll give it to you.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x294D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|59La-la-la...They said I was too loud|11when I practiced in my room.|11|13|12They got mad.|11Sigh...Now I'm sad.|11I'll just stay here all night and|11away from their pad.|10And you are a child, so you must|11go to bed.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x294E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|59La-la-la...They said I was too loud|11when I practiced in my room.|11|13|12They got mad.|11'Til morn, I'll stay here.|11'Til the pain is gone, I'll stay here.|11Do-da-da, do-dee, do-dee...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x294F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, what a cute guest.|11Do you have a reservation?|11Where's your mother?|19|BF", NULL);
