    EZTR_Basic_ReplaceText(0x2951, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm sorry.|11We're totally booked with|11reservations. Please tell that to|11your mother.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2952, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hello, Mr. Scrub.|11How about this rain?|11|13|12Do you scrubs feel sad on rainy|11days, too?|11|13|12....|11But Deku Scrubs are supposed to|11like rain. At least one of us has|11reason to be happy...|BF", NULL);
