    EZTR_Basic_ReplaceText(0x2960, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|59Doo-doo-doooo...|11Though we're running out of time,|11the troupe leader won't wake up.|11|12In time's like this, it means the|11leader has something he's hiding|11from us.|11Do-dee-da-da...|10But the song is done...|E0|BF", NULL);
