    EZTR_Basic_ReplaceText(0x2972, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Before my wedding ceremony I was|11quite happy. I was targeted|11because of what I had been|11turned into.|BF", NULL);
