    EZTR_Basic_ReplaceText(0x29E2, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Now Kafei...|11I've known him since he was real|11little...|11|12But when he showed up looking all|11young in that little |01brat body|00,|11I didn't know what I was seeing! |11 |10All it took was one glance at that|11|01Keaton Mask |00he was carrying for|11me to realize that I was looking|11at my old friend.|10I gave him that mask a long time|11ago when he was just li'l Kafei.|11Didn't know he kept it that well|11for so long...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x29E3, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm not sure why, but...I want to|11give this to you.|E0|BF", NULL);
