    EZTR_Basic_ReplaceText(0x2A32, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|09Oh my. And I thought we would|11finally be able to stock |01Bomb Bags|11|00in our store. What a shame...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A33, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|09Oh my. You think it'll never|11happen to you. Well, now I've|11learned my lesson.|11|12And I thought we would finally be|11able to stock |01Bomb Bags|00 in our|11shop. It's too bad...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A34, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0AThank you. Since he didn't make|11off with them, I can finally stock|11|01Bomb Bags |00at our shop. Maybe I'll|11put 'em out tomorrow.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A35, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0CYes, I must thank you. It's a|11dangerous mask, but maybe you|11could use it to throw your own|11festival fireworks show.|E0|BF", NULL);
