    EZTR_Basic_ReplaceText(0x2A37, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0BAh, well...|11That's a small customer.|11|13|12Be careful during the fireworks.|11You can use bombs once you|11become an adult.|E0|BF", NULL);
