    EZTR_Basic_ReplaceText(0x2A94, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|50Are the fins damp lately?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A95, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What? Mikau???|11|1F|00|0AAm I wrong?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A96, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You look so much like him...|11So sorry, so sorry.|11|13|12Are you here buying fish? With|11the ocean the way it is...|11|13|12All we can do is put up with the|11town's smelly fish, you know...|11|13|12When you get back to Zora Hall,|11give everyone my regards.|11You sure do look like him,|11though...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A97, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "With the ocean the way it is, the|11professor at the lab has started|11raising fish.|11|12See, we don't catch fish anymore.|11We eat them after raising them...|11It's like cultivating vegetables.|11|12I'm thankful and all, but he feeds|11fish to his \"crops.\" Feeding fish to|11fish...That's a scary thought.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A98, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|50That's the greeting used among us|11Zoras.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A99, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, forgive me. I am Toto,|11manager of the band, The|11Indigo-Go's.|11|12I'm out of business cards, so a|11Zora greeting will have to do.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A9A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|50The Indigo-Go's is the popular|11group that we Zora are so proud|11of. They've put out a lot of songs.|11|12One of their hits is|11\"Ballad of the Wind Fish.\"|11You know that song, don't you?|11|12Huh? You don't?|11Really?|11Even one that famous?|11Hmmm...|10You'd be able to hear it if the|11show wasn't canceled. It's such|11a shame.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A9B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|50Canceling the show isn't|11something I want to do at all.|11|13|12It was the first performance at|11the carnival for The Indigo-Go's in|11a while, so I'm sorry for the fans.|11|12But with the diva the way she is|11right now, a show would be...|11|13|12Urr...Lately, only bad things have|11been happening at Zora Hall...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A9C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0DOh my, you...|11|13|13|12You're the one I asked to search|11for Kafei. So did you find|11anything?|11|12...What? What's this?|11You've got nothing?!?|11|13|12Tsk. Tsk.|11Oh, please keep trying!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A9D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0DOh dear, are you on a field trip?|11This is my office. The |01Mayor's|11office|00 is next door.|11|12If you need to speak to me about|11the carnival performances, make|11an appointment, please.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A9E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0DOh dear, are you on a field trip?|11...Or are you the expert person-|11finder I hired?|11|12Yes, yes, yes. I say, you have the|11face of a pro.|11 |11|12The characteristics of the person|11I want you to find..|11Yes, yes. I know them.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2A9F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The person I want you to locate|11is my son, Kafei. You know him,|11don't you? |11...You don't? Really?|10He disappeared about a month ago.|11It's terrible! I'm so very worried...|11I can't get food down my throat,|11and I've lost five pounds.|10You haven't anything, though?|11Oh, dear...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AA0, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well? Could you look for him?|11 |11|02|C2Yes|11No|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AA1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0EOh, that won't do.|11I cannot accept that.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AA2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0EOh my, of course. You are an|11expert. Well, I'm counting on you!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AA3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|80Bah! Bother! Bother! I'm busy!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AA4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|52I am of the Gorman Troupe. I have|11an appointment to meet with|11Madame today...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AA5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, really?|11Then that should be fine if you|11just go in.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AA6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Madame Aroma, I am Gorman.|11It has been some time...|11|13|12Thank you for letting us perform|11at this year's Carnival of Time.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AA7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, dear me...|11Gorman! There's a problem!|19|BF", NULL);
