    EZTR_Basic_ReplaceText(0x2AAE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I am Toto, manager of the Zora|11band, The Indigo-Go's.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AAF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "He arrived this morning.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AB0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|50Actually, there's been an|11unusual accident in Great Bay...|11|13|12And due to this unusual accident,|11Lulu, the diva in The Indigo-Go's,|11has lost her voice.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AB1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Why?|19|BF", NULL);
