    EZTR_Basic_ReplaceText(0x2AB6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|0EIt's off...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AB7, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Bu-but that's!|19|BF", NULL);
