    EZTR_Basic_ReplaceText(0x2AB9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|80Bah! Bother! Bother!|11I'm busy!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ABA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|80I'm angry now!|11Don't speak to me.|11|13|12...They must be joking. Now what|11am I to do?!?|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ABB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6EAll must take refuge!!!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ABC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4FOn with the carnival!!!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ABD, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6EMost of the townsfolk already|11have taken shelter without waiting|11for the Mayor's orders.|11|12The only ones left are public|11servants and committee members...|11|13|12Mr. Mayor and Carnival Committee|11Members, please order those who|11remain to evacuate!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ABE, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|58Ahh...hmm...well...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ABF, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4FYou cowards! Do you actually|11believe the moon will fall?|11|13|12The confused townsfolk simply|11caused a panic by believing this|11ridiculous, groundless theory.|11|12The soldiers couldn't prevent the|11panic, but outside the town walls |11is where the danger is!|11|12You want answers? The answer is|11that the carnival should not be|11canceled!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AC0, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Isn't that right, Mr. Mayor?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AC1, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|6EAre you serious, Mutoh?!?|11|13|13|12It seems that giant chunk of rock|11above us hasn't caught your eye!|11|13|12At this time every year, we are|11overrun by tourists! So why is|11the town empty?|11|12Clearly, it's your job to ensure|11the carnival's operation, but that's|11if people are here for it!|11|12Don't drag the merchants and|11soldiers into this!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AC2, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|58Mmm...Hmm...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AC3, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|4FIf the soldiers wish to run, then|11run, Viscen! We councilmen will|11stick to tradition.|11|12This carnival will be a success!|11I've never heard of a defense unit|11abandoning its town!|11|12Madame Aroma would surely say|11the same thing, wouldn't she,|11Mayor Dotour?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AC4, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...Let's not bring my wife into this.|E0|BF", NULL);
