    EZTR_Basic_ReplaceText(0x2AC9, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The |01Couple's Mask|00. What a nice|11reminder...So, a young couple has|11been married.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ACA, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I wonder...Did my wife flee?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ACB, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|17What!?!|18|11|1F|00|08What did you just say?!?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ACC, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Yes, yes, everyone. We are all|11worried for our families. Why don't|11we end this meeting?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ACD, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "But, Mr. Mayor!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ACE, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This will do. Whether you're|11stubborn and will stay and guard|11your family, or if you'd prefer to|11run far away and seek shelter...|10That is for people to decide on|11their own.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ACF, 0x00, 0x10, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "........!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AD0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Thank you for allowing me to put|11an end to all that pointless|11bickering.|11|12Adults are all so stubborn...|11It is shameful.|11|13|12Here is a token of my gratitude.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AD1, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, I may be an unreliable|11Mayor, but at least my family can|11depend on me. I want to protect|11my wife.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AD2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...I tell you...It's hard to figure|11which way things will go.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AD3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|58...I tell you...It's hard to figure|11which way things will go.|11|13|12See, because Mutoh said he would|11call my wife...|19|BF", NULL);
