    EZTR_Basic_ReplaceText(0x2AD9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|2AWelcome|11Do you have some|11|1F|00|04b|1F|00|04u|1F|00|04s|1F|00|04i|1F|00|04n|1F|00|04e|1F|00|04s|1F|00|04s?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ADA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The room on the left is|11|1F|00|06the Mayor's room...|11|13|12It sounds like they're having some|11kind of |1F|00|06meeting, |1F|00|04I think.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ADB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The room on your right is the|11|1F|00|08drawing room and it's also Madame|11Aroma's office. |BF", NULL);
    EZTR_Basic_ReplaceText(0x2ADC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...My directions...|11Do you want to hear them again?|19|BF", NULL);
