    EZTR_Basic_ReplaceText(0x2ADE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The room on your left is the|11Mayor's Office...|11|13|12And the room on your right is the|11drawing room and it's also Madame|11Aroma's office.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2ADF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The room on your left is|11|1F|00|06The Mayor's office...|11|13|12It sounds like their...|11whatchamacallit... |1F|00|06meeting |1F|00|04ended.|11A lot of tough guys walked out.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AE0, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The room on your right is|11|1F|00|08the drawing room and it's also|11Madame Aroma's office.|11|12Don't go in there without an|11appointment. The lady will get mad|11at you.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AE1, 0x06, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|50Are the fins damp lately?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AE2, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|50Oh. That's the greeting used|11among us Zora.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AE3, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Where's your momma, sonny? Huh?|11You came here by yourself? Well,|11aren't you a big boy?|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AE4, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Once you get older, sonny, come|11see The Indigo-Go's perform live at|11Zora Hall.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AE5, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh dear, are you a student of|11Deku Elementary?|11Where's your teacher?|11|12You shouldn't be here. Field trips|11go next door. Tell your teacher|11that.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AE6, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Did you find your teacher?|11Your teacher's not here???|11Well, then I don't know what to do|11with you...|BF", NULL);
