    EZTR_Basic_ReplaceText(0x2AEB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, Gorman, I wish it was only|11your face that was annoying me|11right now.|BF", NULL);
