    EZTR_Basic_ReplaceText(0x2AF9, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The bar opens at night, sir.|11|13|13|12And it's members-only. We refuse|11people who don't have |01proof of|11membership|00.|11|12Well, now I'm getting things ready,|11so as long as you don't get in the|11way of my cleaning, you can stay.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AFA, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We're called a |01Milk Bar|00, and we|11serve the |03milk of the night|00.|11|13|12Our most popular, of course, is|11|01Chateau Romani|00. It's a vintage|11milk.|11|12It comes from Romani Ranch, and|11the current price is |06200 Rupees|00!|11|13|12...You're not surprised?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AFB, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "There is one more surprising thing|11about this milk...|11|13|12It depends on who you ask, but|11there are those who consider this|11milk as a source of |02Magic Power|00!|11It takes just one gulp they say!|10It's expensive, but thankfully, it's|11the one we serve the most.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AFC, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Last night, we got some fresh|11milk in for the first time in quite|11a while.|11|12Finally, we can feel good about|11our drinks' quality again.|11|13|12But that moon...Our regular|11customers have all fled. So there|11really isn't any good news.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AFD, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "To make things worse, we're short|11on stock.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AFE, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "There is a road to the |01south|00 of|11town called |01Milk Road|00.|11|13This could be someone's prank...|10You see, the road is blocked by a|11huge |01boulder|00.|11|13I can't get any milk in from the|10ranch now, so I can't please my|11customers. It's terrible!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2AFF, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...Are you looking for young Kafei,|11too?|11|13|12It seems Madame Aroma still|11doesn't know where he is...|11But he's not the type to just run|11off!|10He must have a reason for not|11showing himself.|11|13|12Just wait...When the time is right|11and he's ready...he'll show himself.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B00, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "The young one's mask, eh?|11I think it's a waste to look for|11him.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B01, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "What are you staring at?!?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B02, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Sounds like your show has been|11canceled. You don't really need to|11be here anymore.|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B03, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I came to drink!|11I...I'm a customer!!!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B04, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well then, customer, the bar|11opens at |0110 o'clock at night|00.|11Please wait 'til then. And besides|11that...|19|BF", NULL);
