    EZTR_Basic_ReplaceText(0x2B06, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Well, then I don't need milk!|11I just want to sit and think for a|11while... |11|12Just give me a place to do that...|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B07, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Fine. Be my... guest.|E0|BF", NULL);
