    EZTR_Basic_ReplaceText(0x2B0A, 0x06, 0x01, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Welcome...|11 |11|02|C2Speak to shopkeeper|11Have a drink|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B0B, 0x06, 0x01, 0xFE, 0xFFFF, 0x0014, 0x00C8, true, "What'll it be?|11|13|13|12|02|C3Regular Milk: |0620 Rupees|11|02Chateau: |06200 Rupees|11|02Nothing|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B0C, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "You don't have enough |06Rupees|00, sir.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B0D, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Give me a call when you make up|11your mind.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B0E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Members of this club bring their|11own glasses.|11|13|12We ask that you have an empty|11bottle to drink out of when you|11order.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B0F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "There is a road to the |01south|00 of|11town called |01Milk Road|00.|11|13|12Someone must've pulled a prank|11out there, because the road is|11blocked by a huge |01boulder|00.|11|12I can't get any milk in from the|11ranch, so I'm not sure if I should|11recommend the Chateau Romani|11to you.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B10, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...As you can see, all of our|11customers have taken refuge.|11|13|12It may be my undoing, but I'm the|11sort of fellow who'll stay at his|11business through thick and thin.|11|12And I continue standing here|11at the counter hoping one of my|11favorite customers will appear...|11|12And I wasn't wrong.|11See? You stopped in.|BF", NULL);
