    EZTR_Basic_ReplaceText(0x2B12, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I remember when I was back at|11the ranch. My brothers...|11I wonder how they are...|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B13, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Hey ...You!|11|13|13|12Milk...|11|13|13|12It's miiiilk...|11|13|13|12Can you get tipsy from something|11like milk?!? Hic!|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B14, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...What? Hic!|11|13|13|12...Don't look at me! Hic!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B15, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Anyway, I'm just the despised|11second son!|11|13|12I can't handle horses like my older|11brother!|11|13|12I can't take care of horses like|11my younger brother!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B16, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I left the ranch, came to know|11the world of show business...|11Traveled around...|11But for what?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B17, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|68|55...For nothing!!!|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B18, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh, I just had to enter the world|11of entertainment, didn't I?|11It's cold...Soooo cold...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B19, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh dear, are you all right with|11not fleeing?|11|13|12It looks like this is it for this|11town, you know. You saw the|11moon, didn't you? It's gotten so|11huge.|10All the townsfolk have fled. You|11should flee, too. Far away...|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B1A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Oh dear, you're the one searching|11for Kafei.|11|13|12How is it?|11Have you found him?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B1B, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "...Oh dear, is that so?|11You haven't found him...|11|13|12Well, that's enough.|11Good work...|11Now you flee, too...|E0|BF", NULL);
