    EZTR_Basic_ReplaceText(0x2B1E, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "This!!!|11It's from Kafei! Correct?|11Correct?|19|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B1F, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "Wonderful! You really are an|11expert!|11|13|12Yes, yes, I'm sorry.|11My thanks.|11Yes, yes, it is your job, after all.|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B20, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I'm sorry.|11At this point in time, I can give|11you only something like this.|11|12Actually I wanted to give this to|11you sooner...|11Really!|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B21, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "|1E|69|50Hey, are you going to play for us|11again?|E0|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B22, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "I wanted you, too, to hear Lulu's|11voice on this stage.|BF", NULL);
    EZTR_Basic_ReplaceText(0x2B23, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, true, "We were scheduled to do a show,|11but it got canceled.|11|13|12This place has a reputation for|11being a great live venue, so it's|11a shame.|11|12I'd like to do a sound check,|11though. I just want to see what it|11would have been like...|11Hey, you!|19|BF", NULL);
